export type MediaUploadIssue = "file_name" | "unknown" | "processing" | "expired" | "claimed" | "integrity" | "cleanup_unknown" | "rejected" | "too_large" | "dimensions" | "type_mismatch" | "animated" | "unsupported" | "conversion_failed";
