import assert from "node:assert/strict";
import test from "node:test";
import { BrowserHarness, type StubResponse } from "./browser-harness.mts";
import { BrowserNetworkCancelProof } from "./browser-network-cancel-proof.mts";
import { FetchRequestLifecycle, RejectableEventWaiters, invalidInterceptionIdMessage } from "./browser-request-lifecycle.mts";
import { declareLoginReturnAuthPhase, retireDeclaredAuth, takeDeclaredAuthRetirement } from "./browser-declared-auth-retirement.mts";

type Message = { sessionId: string; method: string; params: Record<string, unknown> };
type Input = Parameters<typeof declareLoginReturnAuthPhase>[1];
const session = "declared-auth-session", frame = "declared-auth-frame", loader = "declared-auth-loader";
const authURL = "http://127.0.0.1:3000/auth/me", path = "/auth/me";
const firstNetwork = "declared-auth-network-one", secondNetwork = "declared-auth-network-two";
const firstFetch = "declared-auth-fetch-one", secondFetch = "declared-auth-fetch-two";
const fulfill = "Fetch.fulfillRequest" as const;
const optional: StubResponse = { body: { permissions: ["streams.read"] }, requiredResponse: false, observeBootstrapCancellation: true };
const message = (method: string, params: Record<string, unknown>): Message => ({ sessionId: session, method, params });
const documentEvent = (nextLoader = loader) => message("Page.frameNavigated", { frame: { id: frame, loaderId: nextLoader, url: "http://127.0.0.1:3000/login/" } });
const start = (network = firstNetwork) => message("Network.requestWillBeSent", {
  requestId: network, frameId: frame, loaderId: loader, type: "Fetch", request: { method: "GET", url: authURL },
});
const cancel = (network = firstNetwork) => message("Network.loadingFailed", { requestId: network, canceled: true, errorText: "net::ERR_ABORTED" });
const pause = (id = firstFetch, network = firstNetwork) => message("Fetch.requestPaused", {
  requestId: id, networkId: network, frameId: frame, resourceType: "XHR", request: { method: "GET", url: authURL },
});
const request = (event: Message) => event.params.request as Record<string, unknown>;

function fixture(limit = 2048, initialDocument = documentEvent()) {
  const lifecycle = new FetchRequestLifecycle(), proof = new BrowserNetworkCancelProof(lifecycle, session, limit);
  const state: { frameId: string | undefined; closed: boolean } = { frameId: frame, closed: false };
  const input: Input = {
    lifecycle, session, current: () => ({ generation: lifecycle.generation, ...state }),
    assertHealthy: () => lifecycle.assertHealthy(),
  };
  const emit = (event: Message, generation = lifecycle.generation) => {
    proof.observe(event, generation);
  };
  const registerPause = (event = pause(), required = false) => {
    emit(event);
    const id = String(event.params.requestId), value = request(event), pathname = new URL(String(value.url)).pathname;
    lifecycle.register({ requestId: id, method: String(value.method), pathname, requiredResponse: required });
    proof.registerContract(id, { generation: lifecycle.generation, pathname, optionalFixture: !required });
    return id;
  };
  emit(initialDocument);
  return {
    lifecycle, proof, state, input, emit, registerPause,
    arm: (url = authURL) => declareLoginReturnAuthPhase(proof, input, url),
    retire: (id = firstFetch, response: StubResponse | null = optional) => retireDeclaredAuth(proof, id, response),
  };
}
type Fixture = ReturnType<typeof fixture>;

function harnessFixture(responses: StubResponse[] = [optional]) {
  const lifecycle = new FetchRequestLifecycle(), proof = new BrowserNetworkCancelProof(lifecycle, session);
  const sends: string[] = [], pending = responses.slice();
  const browser = Object.assign(Object.create(BrowserHarness.prototype), {
    sessionId: session, requestLifecycle: lifecycle, networkCancellation: proof,
    requests: new Map<string, number>(), responses: new Map<string, number>(), responseStatuses: new Map<string, number[]>(),
    eventWaiters: new RejectableEventWaiters(), pendingCommands: new Map(), topLevelNavigationEvents: 0,
    topLevelNavigationPending: false, closed: false, fatalError: undefined,
    routeResolver: () => { const response = pending.shift(); assert.ok(response); return response; },
    send: async (command: string) => { sends.push(command); return {}; },
  }) as BrowserHarness;
  const receive = (event: Message) => (browser as unknown as { receive(raw: string): void }).receive(JSON.stringify(event));
  return { browser, lifecycle, proof, sends, receive };
}

function observeCandidate(owner: Fixture) {
  owner.emit(start()); owner.emit(cancel()); owner.registerPause();
}

function assertRejected(owner: Fixture, id = firstFetch, response: StubResponse | null = optional) {
  assert.equal(owner.retire(id, response), false);
  assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
  assert.equal(owner.lifecycle.activeCount, 1);
  const original = new Error(invalidInterceptionIdMessage);
  const attempt = owner.lifecycle.beginSettlement(id, fulfill);
  assert.throws(() => owner.lifecycle.handleSettlementError(attempt, original), error => error === original,
    "a rejected declaration cannot replace the existing current-generation fatal rule");
}

type Mutation = { name: string; mutate: (events: Message[]) => void; required?: boolean; response?: StubResponse | null; limit?: number };
const rejected: Mutation[] = [
  { name: "required response", required: true, response: { ...optional, requiredResponse: true }, mutate() {} },
  { name: "missing explicit bootstrap observation", response: { body: optional.body, requiredResponse: false }, mutate() {} },
  { name: "unhandled route", response: null, mutate() {} },
  { name: "foreign Network session", mutate: events => { events[0].sessionId = "foreign-session"; } },
  { name: "foreign pause session", mutate: events => { events[2].sessionId = "foreign-session"; } },
  { name: "foreign Network frame", mutate: events => { events[0].params.frameId = "foreign-frame"; } },
  { name: "foreign pause frame", mutate: events => { events[2].params.frameId = "foreign-frame"; } },
  { name: "wrong loader", mutate: events => { events[0].params.loaderId = "foreign-loader"; } },
  { name: "wrong Network type", mutate: events => { events[0].params.type = "XHR"; } },
  { name: "wrong pause type", mutate: events => { events[2].params.resourceType = "Fetch"; } },
  { name: "wrong origin", mutate: events => { request(events[0]).url = "http://127.0.0.1:3001/auth/me"; } },
  { name: "query", mutate: events => { request(events[0]).url = authURL + "?extra=one"; } },
  { name: "subpath", mutate: events => { request(events[0]).url = authURL + "/private"; } },
  { name: "different pause URL", mutate: events => { request(events[2]).url = "http://localhost:3000/auth/me"; } },
  { name: "different Network identity", mutate: events => { events[2].params.networkId = secondNetwork; } },
  { name: "redirect", mutate: events => { events[0].params.redirectResponse = {}; } },
  { name: "duplicate SAME Network ID", mutate: events => { events.splice(1, 0, start()); } },
  { name: "duplicate pause", mutate: events => { events.push(pause()); } },
  { name: "two Fetch IDs for one Network ID", mutate: events => { events.push(pause(secondFetch)); } },
  { name: "duplicate cancellation", mutate: events => { events.splice(2, 0, cancel()); } },
  { name: "not canceled", mutate: events => { events[1].params.canceled = false; } },
  { name: "different network error", mutate: events => { events[1].params.errorText = "net::ERR_FAILED"; } },
  { name: "response before cancellation", mutate: events => { events.splice(1, 0, message("Network.responseReceived", { requestId: firstNetwork })); } },
  { name: "finish before cancellation", mutate: events => { events.splice(1, 0, message("Network.loadingFinished", { requestId: firstNetwork })); } },
  { name: "scope replacement", mutate: events => { events.splice(2, 0, documentEvent("replacement-loader")); } },
  { name: "owned frame detach", mutate: events => { events.splice(2, 0, message("Page.frameDetached", { frameId: frame })); } },
  { name: "unknown frame detach", mutate: events => { events.splice(2, 0, message("Page.frameDetached", {})); } },
  { name: "proof overflow", limit: 1, mutate: events => { events.splice(1, 0, start(secondNetwork)); } },
];

export function registerDeclaredAuthRetirementCases() {
  test("declared AUTH actual HH retires first ID while a distinct required second ID completes normally", async () => {
    let release!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; });
    const required: StubResponse = { body: { permissions: ["streams.read"] }, requiredResponse: true, waitUntil: held };
    const { browser, lifecycle, sends, receive } = harnessFixture([required, optional]);
    const active = Reflect.get(lifecycle, "activeRequests") as Map<string, unknown>;
    receive(documentEvent());
    const phase = browser.declareLoginReturnAuthPhase(authURL);
    let idle = false;
    let waiting: Promise<void> | undefined;
    try {
      receive(start()); receive(start(secondNetwork)); receive(cancel()); receive(pause(secondFetch, secondNetwork));
      assert.equal(active.has(secondFetch), true);
      assert.equal(lifecycle.activeCount, 1);
      waiting = browser.waitForRequestHandlersIdle({ timeoutMs: 1_000 }).then(() => { idle = true; });
      void waiting.catch(() => {}); // Awaited after release; preserve earlier assertions on failure.
      await Promise.resolve(); assert.equal(idle, false);
      receive(pause());
      await Promise.resolve();
      browser.assertNoFatalError();
      assert.deepEqual(sends, [], "the browser-cancelled first ID must never reach CDP");
      assert.equal(browser.responses.get(path) || 0, 0);
      assert.equal(browser.responseStatuses.get(path), undefined);
      assert.equal(browser.declaredAuthRetirementCount, 1);
      assert.equal(lifecycle.declaredAuthRetirementCount, 1);
      assert.equal(active.has(firstFetch), false);
      assert.equal(active.has(secondFetch), true, "retiring AUTH1 must preserve the unrelated required AUTH2");
      assert.equal(lifecycle.activeCount, 1);
      assert.equal(idle, false, "global idle must still wait for the held required AUTH2");
      release(); await waiting;
      browser.assertNoFatalError();
      assert.deepEqual(sends, [fulfill], "the distinct required AUTH request retains its normal settlement");
      assert.equal(browser.requests.get(path), 2);
      assert.equal(browser.responses.get(path), 1);
      assert.deepEqual(browser.responseStatuses.get(path), [200]);
      assert.equal(browser.declaredAuthRetirementCount, 1);
      assert.equal(lifecycle.activeCount, 0);
      assert.equal(idle, true);
      assert.equal((Reflect.get(browser, "eventWaiters") as RejectableEventWaiters).pendingCount, 0);
    } finally {
      release(); phase.dispose();
      const cleanup = new Error("declared AUTH fake closed");
      (Reflect.get(browser, "eventWaiters") as RejectableEventWaiters).rejectAll(cleanup);
      if (lifecycle.activeCount) lifecycle.fail(cleanup);
      await waiting?.catch(() => {});
    }
  });

  for (const entry of rejected) test("declared AUTH rejects " + entry.name, () => {
    const owner = fixture(entry.limit), phase = owner.arm(), events = [start(), cancel(), pause()];
    entry.mutate(events);
    let registered = false;
    try {
      for (const event of events) {
        if (event.method === "Fetch.requestPaused" && !registered) { owner.registerPause(event, entry.required); registered = true; }
        else owner.emit(event);
      }
      assert.ok(registered);
      assertRejected(owner, firstFetch, entry.response === undefined ? optional : entry.response);
    } finally { phase.dispose(); }
  });

  for (const method of ["HEAD", "POST", "PUT", "PATCH", "DELETE"]) test("declared AUTH rejects method " + method, () => {
    const owner = fixture(), phase = owner.arm(), first = start(), paused = pause();
    request(first).method = method; request(paused).method = method;
    try { owner.emit(first); owner.emit(cancel()); owner.registerPause(paused); assertRejected(owner); }
    finally { phase.dispose(); }
  });

  for (const late of ["start", "cancel"]) test("declared AUTH cannot arm retrospectively after " + late, () => {
    const { browser, lifecycle, sends, receive } = harnessFixture();
    receive(documentEvent()); receive(start()); if (late === "cancel") receive(cancel());
    assert.throws(() => browser.declareLoginReturnAuthPhase(authURL));
    assert.equal(browser.declaredAuthRetirementCount, 0);
    assert.equal(lifecycle.activeCount, 0);
    assert.deepEqual(sends, []);
  });

  for (const boundary of ["generation-only notification", "return to an already-started loader"]) test("declared AUTH cannot rearm through " + boundary, () => {
    const { browser, lifecycle, sends, receive } = harnessFixture();
    receive(documentEvent()); receive(start());
    lifecycle.beginNavigation("navigate");
    if (boundary === "return to an already-started loader") {
      receive(documentEvent("different-loader"));
      lifecycle.beginNavigation("navigate");
    }
    receive(documentEvent());
    assert.throws(() => browser.declareLoginReturnAuthPhase(authURL));
    assert.equal(browser.declaredAuthRetirementCount, 0);
    assert.equal(lifecycle.activeCount, 0);
    assert.deepEqual(sends, []);
  });

  for (const [label, url] of [
    ["missing", undefined], ["unparseable", ":"],
    ["foreign origin", "https://foreign.invalid/login/"], ["different loopback port", "http://127.0.0.1:3001/login/"],
  ] as const) test("declared AUTH requires a witnessed document origin: " + label, () => {
    const document = documentEvent(), ownedFrame = document.params.frame as Record<string, unknown>;
    if (url === undefined) delete ownedFrame.url;
    else ownedFrame.url = url;
    const owner = fixture(undefined, document);
    assert.throws(() => owner.arm());
    assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
    assert.equal(owner.lifecycle.activeCount, 0);
  });

  test("declared AUTH first successful start consumes the phase and second cancellation cannot retire", () => {
    const owner = fixture(), phase = owner.arm();
    try {
      owner.emit(start());
      owner.emit(message("Network.responseReceived", { requestId: firstNetwork }));
      owner.emit(message("Network.loadingFinished", { requestId: firstNetwork }));
      owner.emit(start(secondNetwork)); owner.emit(cancel(secondNetwork)); owner.registerPause(pause(secondFetch, secondNetwork));
      assertRejected(owner, secondFetch);
    } finally { phase.dispose(); }
  });

  test("declared AUTH rejects evidence from a different generation", () => {
    const owner = fixture(), phase = owner.arm();
    try {
      owner.emit(start(), owner.lifecycle.generation + 1); owner.emit(cancel(), owner.lifecycle.generation + 1);
      owner.registerPause(); assertRejected(owner);
    } finally { phase.dispose(); }
  });

  test("declared AUTH disposal and same-document rearm cannot revive a capability", () => {
    const owner = fixture(), phase = owner.arm(); phase.dispose();
    assert.throws(() => owner.arm());
    owner.emit(documentEvent());
    assert.throws(() => owner.arm(), "a repeated notification of the same frame/loader/generation is not a new document");
    observeCandidate(owner); assertRejected(owner);
  });

  test("declared AUTH closed and fatal owners retain refusal and fatal identity", () => {
    const closed = fixture(), closedPhase = closed.arm();
    try { observeCandidate(closed); closed.state.closed = true; assertRejected(closed); }
    finally { closedPhase.dispose(); }
    const owner = fixture(), phase = owner.arm(), fatal = new Error("owned declared AUTH fatal");
    try {
      observeCandidate(owner); owner.lifecycle.fail(fatal);
      assert.throws(() => owner.retire(), error => error === fatal);
      assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
    } finally { phase.dispose(); }
  });

  test("declared AUTH cannot follow a rejected old first claim", () => {
    const owner = fixture(), phase = owner.arm();
    try {
      observeCandidate(owner);
      assert.equal(owner.proof.claimBeforeSettlement(firstFetch, fulfill, owner.input.current()), undefined);
      assertRejected(owner);
    } finally { phase.dispose(); }
  });

  test("declared AUTH receipt is opaque, frozen, one-use and releases the actual lifecycle idle waiter", async () => {
    const owner = fixture(), phase = owner.arm(), complete = owner.lifecycle.completeDeclaredAuthRetirement.bind(owner.lifecycle);
    let receipt: unknown;
    owner.lifecycle.completeDeclaredAuthRetirement = (id, value) => {
      receipt = value; assert.deepEqual(Object.keys(value as object), []); assert.equal(Object.isFrozen(value), true);
      return complete(id, value);
    };
    try {
      observeCandidate(owner);
      let idle = false;
      const waiting = owner.lifecycle.waitForIdle({ pathname: path, timeoutMs: 100 }).then(() => { idle = true; });
      void waiting.catch(() => {}); // Awaited below; also observe a rejection if an earlier assertion fails.
      await Promise.resolve(); assert.equal(idle, false);
      assert.equal(owner.retire(), true); await waiting;
      assert.equal(idle, true); assert.equal(owner.lifecycle.activeCount, 0); assert.equal(owner.lifecycle.declaredAuthRetirementCount, 1);
      assert.equal(takeDeclaredAuthRetirement(receipt, owner.lifecycle, firstFetch, owner.lifecycle.generation), false);
      assert.equal(takeDeclaredAuthRetirement(Object.freeze({}), owner.lifecycle, firstFetch, owner.lifecycle.generation), false);
      assert.equal(owner.retire(), false);
    } finally {
      phase.dispose();
      if (owner.lifecycle.activeCount) owner.lifecycle.fail(new Error("declared AUTH fake closed"));
    }
  });

  for (const fault of ["owner", "id", "generation", "attempt", "required", "disposed"]) test("declared AUTH actual receipt independently rejects " + fault, () => {
    const owner = fixture(), phase = owner.arm(), complete = owner.lifecycle.completeDeclaredAuthRetirement.bind(owner.lifecycle);
    owner.lifecycle.completeDeclaredAuthRetirement = (id, value) => {
      if (fault === "attempt") owner.lifecycle.beginSettlement(id, fulfill);
      else if (fault === "required") owner.lifecycle.setRequiredResponse(id, true);
      else if (fault === "disposed") phase.dispose();
      else assert.equal(takeDeclaredAuthRetirement(value, fault === "owner" ? {} : owner.lifecycle,
        fault === "id" ? "foreign-fetch" : id, fault === "generation" ? owner.lifecycle.generation + 1 : owner.lifecycle.generation), false);
      return complete(id, value);
    };
    try {
      observeCandidate(owner);
      assert.throws(() => owner.retire(), /declared|retirement|receipt/i);
      assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0); assert.equal(owner.lifecycle.activeCount, 1);
      assert.equal(owner.retire(), false, "failed terminal validation burns the first boundary");
    } finally { phase.dispose(); }
  });

  test("declared AUTH start-loader history overflow stays closed after parent document ledgers retire", () => {
    const owner = fixture();
    for (let index = 0; index < 2049; index += 1) {
      const nextLoader = `history-loader-${index}`;
      owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent(nextLoader));
      const event = start(`history-network-${index}`); event.params.loaderId = nextLoader; owner.emit(event);
    }
    assert.equal(owner.proof.overflowed, false, "the parent proof cleared each old document ledger normally");
    owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent("history-fresh-loader"));
    assert.throws(() => owner.arm(), "new AUTH history overflow must reject an otherwise fresh document");
    owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent("history-later-loader"));
    assert.throws(() => owner.arm(), "a later document cannot clear the bounded history refusal");
    assert.equal(owner.proof.overflowed, false);
    assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
  });

  test("declared AUTH declaration history cannot exceed 2048 or revive in another fresh loader", () => {
    const owner = fixture();
    for (let index = 0; index < 2048; index += 1) {
      owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent(`declared-loader-${index}`));
      owner.arm().dispose();
    }
    owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent("declaration-overflow-loader"));
    assert.throws(() => owner.arm(), /capacity exceeded/);
    owner.lifecycle.beginNavigation("navigate"); owner.emit(documentEvent("declaration-no-revival-loader"));
    assert.throws(() => owner.arm());
    assert.equal(owner.proof.overflowed, false);
    assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
  });

  test("declared AUTH declaration rejects foreign proof identity and noncanonical URLs", () => {
    const owner = fixture();
    assert.throws(() => declareLoginReturnAuthPhase(owner.proof, { ...owner.input, lifecycle: new FetchRequestLifecycle() }, authURL));
    assert.throws(() => declareLoginReturnAuthPhase(owner.proof, { ...owner.input, session: "foreign-session" }, authURL));
    for (const url of ["https://foreign.invalid/auth/me", authURL + "?x=one", authURL + "#hash", authURL + "/private", "http://user@127.0.0.1:3000/auth/me"]) {
      assert.throws(() => owner.arm(url), TypeError);
    }
    owner.state.frameId = "foreign-main-frame";
    assert.throws(() => owner.arm());
    const missing = fixture(); missing.emit(message("Page.frameDetached", {}));
    assert.throws(() => missing.arm());
  });
}

import type { BrowserNetworkCancelProof } from "./browser-network-cancel-proof.mts";
import type { FetchRequestLifecycle } from "./browser-request-lifecycle.mts";
import type { StubResponse } from "./browser-harness.mts";

type Scope = NonNullable<ReturnType<BrowserNetworkCancelProof["ownedDocument"]>>;
type Current = { generation: number; frameId: string | undefined; closed: boolean };
type Input = { lifecycle: FetchRequestLifecycle; session: string; current: () => Current; assertHealthy: () => void };
type Message = { sessionId?: unknown; method?: unknown; params?: unknown };
type Values = Record<string, unknown>;
type ReadPath = "/auth/me" | "/version";
type StartHistory = { loaders: Set<string>; invalid: boolean };
type OwnedDocuments = { current: string | undefined; retired: Set<string>; invalid: boolean };
type Bound = {
  id: string; start: number; invalid: boolean; url: string; frame: string; loader: string;
  generation: number; starts: number; response: boolean; finished: boolean;
  cancel?: { order: number; exact: boolean; generation: number };
  pause?: { id: string; order: number; generation: number; frame: string; url: string; valid: boolean };
};
type Phase = { scope: Scope; url: string; origin: string; declaration: number; active: boolean; consumed: boolean; bound?: Bound };
type ReceiptData = { owner: object; id: string; generation: number; path: ReadPath; validate: () => boolean };
const receipts = new WeakMap<object, ReceiptData>();
const managers = new WeakMap<BrowserNetworkCancelProof, Map<ReadPath, DeclaredAuthPhase>>();
const documentOrigins = new WeakMap<Scope, string>();
const readStartHistory = new WeakMap<BrowserNetworkCancelProof, Map<ReadPath, StartHistory>>();
const ownedDocuments = new WeakMap<BrowserNetworkCancelProof, OwnedDocuments>();
const values = (value: unknown): Values | undefined => value !== null && typeof value === "object" && !Array.isArray(value) ? value as Values : undefined;
const identifier = (value: unknown): value is string => typeof value === "string" && value.length > 0 && value.length <= 256;

function exactReadURL(value: string, path: ReadPath) {
  const url = new URL(value);
  if (!["http:", "https:"].includes(url.protocol) || !["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)
    || url.pathname !== path || url.search || url.hash || url.username || url.password || url.href !== value) {
    throw new TypeError("A canonical loopback bootstrap read URL is required");
  }
  return url.href;
}

// A separate receipt family: it cannot be used as an existing Network ticket.
export function takeDeclaredAuthRetirement(value: unknown, owner: object, id: string, generation: number) {
  if (value === null || typeof value !== "object") return false;
  const receipt = receipts.get(value);
  receipts.delete(value);
  return !!receipt && receipt.path === "/auth/me" && receipt.owner === owner && receipt.id === id && receipt.generation === generation && receipt.validate();
}

export function takeDeclaredVersionRetirement(value: unknown, owner: object, id: string, generation: number) {
  if (value === null || typeof value !== "object") return false;
  const receipt = receipts.get(value);
  receipts.delete(value);
  return !!receipt && receipt.path === "/version" && receipt.owner === owner && receipt.id === id && receipt.generation === generation && receipt.validate();
}

export function isKnownForeignDocumentLoader(proof: BrowserNetworkCancelProof, scope: { loader: string } | undefined, loader: string | undefined) {
  const history = ownedDocuments.get(proof);
  return !!scope && identifier(loader) && loader !== scope.loader && !history?.invalid && history?.retired.has(loader) === true;
}

class DeclaredAuthPhase {
  private readonly proof: BrowserNetworkCancelProof;
  private readonly path: ReadPath;
  readonly input: Input;
  private readonly seenScopes = new WeakSet<object>();
  private readonly seenLoaders = new Set<string>();
  private readonly networkIDs = new Set<string>();
  private readonly fetchIDs = new Set<string>();
  private readonly earlyTerminalIDs = new Set<string>();
  private phase: Phase | undefined;
  private order = 0;
  private declarations = 0;
  private disabled = false;

  constructor(proof: BrowserNetworkCancelProof, input: Input, path: ReadPath) { this.proof = proof; this.input = input; this.path = path; }

  private next() {
    if (this.order >= Number.MAX_SAFE_INTEGER) this.disabled = true;
    return ++this.order;
  }

  private live(phase: Phase) {
    this.input.assertHealthy();
    const current = this.input.current();
    return !this.disabled && phase.active && !current.closed && !this.proof.overflowed && !ownedDocuments.get(this.proof)?.invalid && !readStartHistory.get(this.proof)?.get(this.path)?.invalid
      && this.proof.ownedDocument(current) === phase.scope && documentOrigins.get(phase.scope) === phase.origin;
  }

  declare(url: string) {
    this.input.assertHealthy();
    const current = this.input.current(), scope = this.proof.ownedDocument(current), origin = new URL(url).origin;
    if (current.closed || !scope || this.disabled || this.phase?.active || this.seenScopes.has(scope) || this.seenLoaders.has(scope.loader)) throw new Error("LoginReturn read phase requires a fresh owned document scope");
    if (this.declarations >= 2048) { this.disabled = true; throw new Error("Declared read phase capacity exceeded"); }
    const history = readStartHistory.get(this.proof)?.get(this.path);
    if (ownedDocuments.get(this.proof)?.invalid || history?.invalid || history?.loaders.has(scope.loader)
      || documentOrigins.get(scope) !== origin || !this.proof.canDeclareAuthBeforeStart(scope, url)) throw new Error("LoginReturn read phase requires a same-origin document before its first read start");
    this.declarations += 1;
    this.seenScopes.add(scope);
    this.seenLoaders.add(scope.loader);
    const phase: Phase = { scope, url, origin, declaration: this.next(), active: true, consumed: false };
    this.phase = phase;
    this.earlyTerminalIDs.clear();
    return Object.freeze({ dispose: () => { phase.active = false; } });
  }

  observe(message: Message, generation: number) {
    const phase = this.phase;
    if (!phase?.active) return;
    try {
      if (!this.live(phase)) { phase.active = false; return; }
      if (message.sessionId !== this.input.session) return;
      const params = values(message.params);
      if (!params || !Number.isSafeInteger(generation) || generation !== phase.scope.generation) { phase.active = false; return; }
      if (!["Network.requestWillBeSent", "Network.loadingFailed", "Network.loadingFinished", "Network.responseReceived", "Fetch.requestPaused"].includes(String(message.method))) return;
      const order = this.next(), bound = phase.bound;
      if (message.method === "Network.requestWillBeSent") {
        const request = values(params.request);
        if (bound && params.requestId === bound.id) { bound.starts += 1; bound.invalid = true; return; }
        const id = params.requestId;
        if (!identifier(id)) { phase.active = false; return; }
        const reused = this.networkIDs.has(id);
        if (!reused && this.networkIDs.size >= 2048) { this.disabled = true; return; }
        this.networkIDs.add(id);
        // A distinct second start never replaces or invalidates the first ID.
        if (phase.consumed || request?.url !== phase.url) return;
        if (isKnownForeignDocumentLoader(this.proof, phase.scope, identifier(params.loaderId) ? params.loaderId : undefined)) return;
        phase.consumed = true;
        const frame = params.frameId, loader = params.loaderId;
        if (!identifier(frame) || !identifier(loader)) { phase.active = false; return; }
        phase.bound = { id, frame, loader, url: phase.url, generation, start: order, starts: 1, response: false, finished: false,
          invalid: reused || this.earlyTerminalIDs.has(id) || request.method !== "GET" || params.type !== "Fetch"
            || params.redirectResponse !== undefined || frame !== phase.scope.frame || loader !== phase.scope.loader };
        return;
      }
      if (message.method === "Fetch.requestPaused") {
        if (!bound || params.networkId !== bound.id) return;
        const request = values(params.request), id = params.requestId, frame = params.frameId;
        if (bound.pause || !identifier(id) || !identifier(frame)) { bound.invalid = true; return; }
        if (this.fetchIDs.size >= 2048) { this.disabled = true; return; }
        const reused = this.fetchIDs.has(id);
        this.fetchIDs.add(id);
        bound.pause = { id, frame, order, generation, url: typeof request?.url === "string" ? request.url : "",
          valid: !reused && request?.method === "GET" && request.url === bound.url && frame === bound.frame && params.resourceType === "XHR"
            && params.responseStatusCode === undefined && params.responseErrorReason === undefined };
        return;
      }
      const id = params.requestId;
      if (!identifier(id)) { phase.active = false; return; }
      if (!bound || id !== bound.id) {
        if (!bound) {
          if (this.earlyTerminalIDs.size >= 2048) this.disabled = true;
          else this.earlyTerminalIDs.add(id);
        }
        return;
      }
      if (message.method === "Network.loadingFailed") {
        if (bound.cancel) bound.invalid = true;
        bound.cancel = { order, generation, exact: params.canceled === true && params.errorText === "net::ERR_ABORTED" };
      } else if (message.method === "Network.responseReceived") bound.response = true;
      else bound.finished = true;
    } catch { phase.active = false; }
  }

  retire(id: string, response: StubResponse | null) {
    const phase = this.phase, bound = phase?.bound, pause = bound?.pause, cancel = bound?.cancel;
    if (!phase || !bound || !pause || !cancel || pause.id !== id || !this.live(phase)
      || bound.invalid || !pause.valid || bound.starts !== 1 || !cancel.exact || bound.response || bound.finished
      || bound.generation !== phase.scope.generation || pause.generation !== bound.generation || cancel.generation !== bound.generation
      || !(phase.declaration < bound.start && bound.start < cancel.order && cancel.order < pause.order)
      || response === null || response.requiredResponse !== false || response.observeBootstrapCancellation !== true) return false;
    // This uses the original proof's attempted-ID set. A failed old claim cannot
    // be followed by this transition, nor can this transition authorize a retry.
    const reserved = this.path === "/auth/me" ? this.proof.reserveDeclaredRetirementBoundary(id, phase.scope) : this.proof.reserveDeclaredVersionRetirementBoundary(id, phase.scope);
    if (!reserved) return false;
    const receipt = Object.freeze({});
    receipts.set(receipt, { owner: this.input.lifecycle, id, generation: bound.generation, path: this.path,
      validate: () => this.phase === phase && this.live(phase) && !bound.invalid && pause.valid
        && !bound.response && !bound.finished && bound.pause === pause && bound.cancel === cancel });
    if (this.path === "/auth/me") this.input.lifecycle.completeDeclaredAuthRetirement(id, receipt);
    else this.input.lifecycle.completeDeclaredVersionRetirement(id, receipt);
    phase.active = false;
    return true;
  }

  matchesFetch(id: string) { return this.phase?.bound?.pause?.id === id; }
}

function declareRead(proof: BrowserNetworkCancelProof | undefined, input: Input, path: ReadPath, url: string) {
  if (!proof || !proof.ownsLifecycle(input.lifecycle, input.session)) throw new Error("An owned Network proof is required for LoginReturn bootstrap");
  const exactURL = exactReadURL(url, path);
  let lanes = managers.get(proof);
  if (!lanes) { lanes = new Map(); managers.set(proof, lanes); }
  let manager = lanes.get(path);
  if (!manager) { manager = new DeclaredAuthPhase(proof, input, path); lanes.set(path, manager); }
  if (manager.input.lifecycle !== input.lifecycle || manager.input.session !== input.session) throw new Error("Declared AUTH owner mismatch");
  return manager.declare(exactURL);
}

export function declareLoginReturnAuthPhase(proof: BrowserNetworkCancelProof | undefined, input: Input, url: string) {
  return declareRead(proof, input, "/auth/me", url);
}

export function declareLoginReturnBootstrapPhase(proof: BrowserNetworkCancelProof | undefined, input: Input, baseURL: string) {
  const auth = declareRead(proof, input, "/auth/me", new URL("/auth/me", baseURL).href);
  try {
    const version = declareRead(proof, input, "/version", new URL("/version", baseURL).href);
    return Object.freeze({ dispose: () => { auth.dispose(); version.dispose(); } });
  } catch (error) { auth.dispose(); throw error; }
}

export function observeDeclaredAuthRetirement(proof: BrowserNetworkCancelProof, message: Message, generation: number) {
  // The existing parser has already processed this event. Keep only the origin
  // witnessed for that exact opaque owned scope; unknown URLs have no fallback.
  try {
    if (message.method === "Network.requestWillBeSent" && proof.ownsSession(message.sessionId)) {
      const params = values(message.params), request = values(params?.request);
      const path = typeof request?.url === "string" && request.url.length <= 4096 ? new URL(request.url).pathname : undefined;
      if (path === "/auth/me" || path === "/version") {
        let histories = readStartHistory.get(proof);
        if (!histories) { histories = new Map(); readStartHistory.set(proof, histories); }
        let history = histories.get(path);
        if (!history) { history = { loaders: new Set(), invalid: false }; histories.set(path, history); }
        const loader = params?.loaderId;
        const documents = ownedDocuments.get(proof);
        if (!identifier(loader) || !Number.isSafeInteger(generation) || !documents || documents.invalid
          || loader !== documents.current && !documents.retired.has(loader)) history.invalid = true;
        else if (!history.loaders.has(loader) && history.loaders.size >= 2048) history.invalid = true;
        else history.loaders.add(loader);
      }
    }
    if (message.method === "Page.frameNavigated" && proof.ownsSession(message.sessionId)) {
      const frame = values(values(message.params)?.frame);
      const scope = identifier(frame?.id) ? proof.ownedDocument({ generation, frameId: frame.id }) : undefined;
      if (scope) {
        let documents = ownedDocuments.get(proof);
        if (!documents) { documents = { current: undefined, retired: new Set(), invalid: false }; ownedDocuments.set(proof, documents); }
        if (documents.current !== undefined && documents.current !== scope.loader && !documents.retired.has(documents.current)) {
          if (documents.retired.size >= 2048) documents.invalid = true;
          else documents.retired.add(documents.current);
        }
        documents.current = scope.loader;
      }
      if (scope && typeof frame?.url === "string" && frame.url.length <= 8192) {
        const url = new URL(frame.url);
        if (["http:", "https:"].includes(url.protocol)) documentOrigins.set(scope, url.origin);
      }
    }
  } catch { /* An unavailable origin witness cannot authorize a declaration. */ }
  for (const lane of managers.get(proof)?.values() ?? []) lane.observe(message, generation);
}

export function retireDeclaredAuth(proof: BrowserNetworkCancelProof | undefined, id: string, response: StubResponse | null) {
  return !!proof && (managers.get(proof)?.get("/auth/me")?.retire(id, response) ?? false);
}

export function retireDeclaredBootstrap(proof: BrowserNetworkCancelProof | undefined, id: string, response: StubResponse | null) {
  if (!proof) return false;
  const matching = [...(managers.get(proof)?.values() ?? [])].filter(lane => lane.matchesFetch(id));
  return matching.length === 1 && matching[0].retire(id, response);
}

import assert from "node:assert/strict";
import test from "node:test";
import { BrowserHarness, type StubResponse } from "./browser-harness.mts";
import { BrowserNetworkCancelProof } from "./browser-network-cancel-proof.mts";
import { FetchRequestLifecycle, RejectableEventWaiters, invalidInterceptionIdMessage } from "./browser-request-lifecycle.mts";
import {
  declareLoginReturnAuthPhase, declareLoginReturnBootstrapPhase, retireDeclaredBootstrap,
  takeDeclaredAuthRetirement, takeDeclaredVersionRetirement,
} from "./browser-declared-auth-retirement.mts";

type Message = { sessionId: string; method: string; params: Record<string, unknown> };
type Input = Parameters<typeof declareLoginReturnBootstrapPhase>[1];
type Lane = "/auth/me" | "/version";
const session = "declared-version-session", frame = "declared-version-frame", loader = "declared-version-loader";
const baseURL = "http://127.0.0.1:3000", version: Lane = "/version", auth: Lane = "/auth/me";
const firstNetwork = "declared-version-first-network", secondNetwork = "declared-version-second-network";
const firstFetch = "declared-version-first-fetch", secondFetch = "declared-version-second-fetch";
const fulfill = "Fetch.fulfillRequest" as const;
const optional: StubResponse = { body: { version: "test-version" }, requiredResponse: false, observeBootstrapCancellation: true };
const required: StubResponse = { body: { version: "test-version" }, requiredResponse: true };
const message = (method: string, params: Record<string, unknown>): Message => ({ sessionId: session, method, params });
const documentEvent = (nextLoader = loader) => message("Page.frameNavigated", { frame: { id: frame, loaderId: nextLoader, url: baseURL + "/login/" } });
const start = (path: string = version, network = firstNetwork, nextLoader = loader) => message("Network.requestWillBeSent", {
  requestId: network, frameId: frame, loaderId: nextLoader, type: "Fetch", request: { method: "GET", url: baseURL + path },
});
const cancel = (network = firstNetwork) => message("Network.loadingFailed", { requestId: network, canceled: true, errorText: "net::ERR_ABORTED" });
const pause = (path: string = version, id = firstFetch, network = firstNetwork) => message("Fetch.requestPaused", {
  requestId: id, networkId: network, frameId: frame, resourceType: "XHR", request: { method: "GET", url: baseURL + path },
});
const request = (event: Message) => event.params.request as Record<string, unknown>;

function fixture(limit = 2048, initialDocument = documentEvent()) {
  const lifecycle = new FetchRequestLifecycle(), proof = new BrowserNetworkCancelProof(lifecycle, session, limit);
  const state: { frameId: string | undefined; closed: boolean } = { frameId: frame, closed: false };
  const input: Input = { lifecycle, session, current: () => ({ generation: lifecycle.generation, ...state }), assertHealthy: () => lifecycle.assertHealthy() };
  const emit = (event: Message, generation = lifecycle.generation) => proof.observe(event, generation);
  const registerPause = (event = pause(), requiredResponse = false) => {
    emit(event);
    const id = String(event.params.requestId), value = request(event), pathname = new URL(String(value.url)).pathname;
    lifecycle.register({ requestId: id, method: String(value.method), pathname, requiredResponse });
    proof.registerContract(id, { generation: lifecycle.generation, pathname, optionalFixture: !requiredResponse });
    return id;
  };
  emit(initialDocument);
  return {
    lifecycle, proof, input, state, emit, registerPause,
    arm: (url = baseURL) => declareLoginReturnBootstrapPhase(proof, input, url),
    retire: (id = firstFetch, response: StubResponse | null = optional) => retireDeclaredBootstrap(proof, id, response),
  };
}
type Fixture = ReturnType<typeof fixture>;

function harnessFixture(responses: StubResponse[]) {
  const lifecycle = new FetchRequestLifecycle(), proof = new BrowserNetworkCancelProof(lifecycle, session);
  const sends: string[] = [], pending = responses.slice();
  const browser = Object.assign(Object.create(BrowserHarness.prototype), {
    sessionId: session, requestLifecycle: lifecycle, networkCancellation: proof,
    requests: new Map<string, number>(), responses: new Map<string, number>(), responseStatuses: new Map<string, number[]>(),
    eventWaiters: new RejectableEventWaiters(), pendingCommands: new Map(), topLevelNavigationEvents: 0,
    topLevelNavigationPending: false, closed: false, fatalError: undefined,
    routeResolver: () => { const response = pending.shift(); assert.ok(response); return response; },
    send: async (command: string) => { sends.push(command); return {}; },
  }) as BrowserHarness;
  const receive = (event: Message) => (browser as unknown as { receive(raw: string): void }).receive(JSON.stringify(event));
  return { browser, lifecycle, sends, receive };
}

function candidate(owner: Fixture, path: string = version, id = firstFetch, network = firstNetwork) {
  owner.emit(start(path, network)); owner.emit(cancel(network)); owner.registerPause(pause(path, id, network));
}

function assertRejected(owner: Fixture, id = firstFetch, response: StubResponse | null = optional) {
  assert.equal(owner.retire(id, response), false);
  assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0);
  assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
  assert.equal(owner.lifecycle.activeCount, 1);
  const original = new Error(invalidInterceptionIdMessage), attempt = owner.lifecycle.beginSettlement(id, fulfill);
  assert.throws(() => owner.lifecycle.handleSettlementError(attempt, original), error => error === original,
    "an unproved VERSION must preserve the existing current-generation fatal error object");
}

type Refusal = { name: string; mutate: (events: Message[]) => void; required?: boolean; response?: StubResponse | null; limit?: number };
const refusals: Refusal[] = [
  { name: "required GET", required: true, response: { ...optional, requiredResponse: true }, mutate() {} },
  { name: "missing bootstrap flag", response: { body: optional.body, requiredResponse: false }, mutate() {} },
  { name: "unhandled response", response: null, mutate() {} },
  { name: "foreign Network session", mutate: e => { e[0].sessionId = "foreign-session"; } },
  { name: "foreign pause session", mutate: e => { e[2].sessionId = "foreign-session"; } },
  { name: "foreign Network frame", mutate: e => { e[0].params.frameId = "foreign-frame"; } },
  { name: "foreign pause frame", mutate: e => { e[2].params.frameId = "foreign-frame"; } },
  { name: "missing loader", mutate: e => { delete e[0].params.loaderId; } },
  { name: "wrong Network type", mutate: e => { e[0].params.type = "XHR"; } },
  { name: "wrong pause type", mutate: e => { e[2].params.resourceType = "Fetch"; } },
  { name: "different origin", mutate: e => { request(e[0]).url = "http://127.0.0.1:3001/version"; } },
  { name: "query", mutate: e => { request(e[0]).url = baseURL + "/version?extra=one"; } },
  { name: "subpath", mutate: e => { request(e[0]).url = baseURL + "/version/private"; } },
  { name: "duplicate Network ID", mutate: e => { e.splice(1, 0, start()); } },
  { name: "duplicate pause", mutate: e => { e.push(pause()); } },
  { name: "duplicate cancel", mutate: e => { e.splice(2, 0, cancel()); } },
  { name: "wrong Network join", mutate: e => { e[2].params.networkId = secondNetwork; } },
  { name: "response before cancel", mutate: e => { e.splice(1, 0, message("Network.responseReceived", { requestId: firstNetwork })); } },
  { name: "finish before cancel", mutate: e => { e.splice(1, 0, message("Network.loadingFinished", { requestId: firstNetwork })); } },
  { name: "not cancelled", mutate: e => { e[1].params.canceled = false; } },
  { name: "scope replacement", mutate: e => { e.splice(2, 0, documentEvent("replacement-loader")); } },
  { name: "owned detach", mutate: e => { e.splice(2, 0, message("Page.frameDetached", { frameId: frame })); } },
  { name: "proof overflow", limit: 1, mutate: e => { e.splice(1, 0, start("/unrelated", secondNetwork)); } },
];

export function registerDeclaredVersionRetirementCases() {
  test("declared VERSION actual HH retirement preserves a held required second VERSION and global idle", async () => {
    let release!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; });
    const { browser, lifecycle, sends, receive } = harnessFixture([{ ...required, waitUntil: held }, optional]);
    const active = Reflect.get(lifecycle, "activeRequests") as Map<string, unknown>;
    receive(documentEvent());
    const phase = browser.declareLoginReturnBootstrapPhase(baseURL);
    let idle = false;
    let waiting: Promise<void> | undefined;
    try {
      receive(start()); receive(start(version, secondNetwork)); receive(cancel()); receive(pause(version, secondFetch, secondNetwork));
      assert.equal(active.has(secondFetch), true);
      waiting = browser.waitForRequestHandlersIdle({ timeoutMs: 1_000 }).then(() => { idle = true; });
      void waiting.catch(() => {});
      await Promise.resolve(); assert.equal(idle, false);
      receive(pause()); await Promise.resolve(); browser.assertNoFatalError();
      assert.deepEqual(sends, []); assert.equal(browser.responses.get(version) || 0, 0);
      assert.equal(browser.responseStatuses.get(version), undefined);
      assert.equal(lifecycle.declaredVersionRetirementCount, 1); assert.equal(browser.declaredAuthRetirementCount, 0);
      assert.equal(active.has(firstFetch), false); assert.equal(active.has(secondFetch), true);
      assert.equal(lifecycle.activeCount, 1); assert.equal(idle, false);
      release(); await waiting; browser.assertNoFatalError();
      assert.deepEqual(sends, [fulfill]); assert.equal(browser.requests.get(version), 2);
      assert.equal(browser.responses.get(version), 1); assert.deepEqual(browser.responseStatuses.get(version), [200]);
      assert.equal(lifecycle.declaredVersionRetirementCount, 1); assert.equal(lifecycle.preSettlementCancellationCount, 0);
      assert.equal(lifecycle.activeCount, 0); assert.equal(idle, true);
    } finally {
      release(); phase.dispose();
      const cleanup = new Error("declared VERSION fake closed");
      (Reflect.get(browser, "eventWaiters") as RejectableEventWaiters).rejectAll(cleanup);
      if (lifecycle.activeCount) lifecycle.fail(cleanup);
      await waiting?.catch(() => {});
    }
  });

  for (const successful of [auth, version]) test("declared bootstrap actual HH " + successful + " success leaves the other lane's first retirement available", async () => {
    const retired = successful === auth ? version : auth;
    const { browser, lifecycle, sends, receive } = harnessFixture([required, optional]);
    receive(documentEvent()); const phase = browser.declareLoginReturnBootstrapPhase(baseURL);
    try {
      receive(start(successful)); receive(pause(successful));
      await browser.waitForRequestHandlersIdle({ timeoutMs: 1_000 }); browser.assertNoFatalError();
      assert.deepEqual(sends, [fulfill]); assert.equal(browser.responses.get(successful), 1);
      assert.deepEqual(browser.responseStatuses.get(successful), [200]);
      assert.equal(browser.declaredAuthRetirementCount, 0); assert.equal(lifecycle.declaredVersionRetirementCount, 0);
      receive(start(retired, secondNetwork)); receive(cancel(secondNetwork)); receive(pause(retired, secondFetch, secondNetwork));
      await browser.waitForRequestHandlersIdle({ timeoutMs: 1_000 }); browser.assertNoFatalError();
      assert.deepEqual(sends, [fulfill]); assert.equal(browser.responses.get(retired) || 0, 0);
      assert.equal(browser.responseStatuses.get(retired), undefined);
      assert.equal(browser.declaredAuthRetirementCount, retired === auth ? 1 : 0);
      assert.equal(lifecycle.declaredVersionRetirementCount, retired === version ? 1 : 0);
      assert.equal(lifecycle.activeCount, 0); assert.equal(lifecycle.preSettlementCancellationCount, 0);
    } finally { phase.dispose(); }
  });

  for (const timing of ["before declaration", "after declaration"]) test("declared VERSION known foreign loader does not consume the current document: " + timing, () => {
    const known = "known-previous-loader", owner = fixture(2048, documentEvent(known));
    owner.emit(documentEvent());
    if (timing === "before declaration") owner.emit(start(version, "known-foreign-network", known));
    const phase = owner.arm();
    try {
      if (timing === "after declaration") owner.emit(start(version, "known-foreign-network", known));
      candidate(owner); assert.equal(owner.retire(), true);
      assert.equal(owner.lifecycle.declaredVersionRetirementCount, 1); assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0);
      assert.equal(owner.lifecycle.activeCount, 0); assert.equal(owner.retire("known-foreign-fetch"), false);
    } finally { phase.dispose(); }
  });

  for (const timing of ["before declaration", "after declaration"]) test("declared VERSION unknown same-epoch loader cannot authorize a later current start: " + timing, () => {
    const owner = fixture(), unknown = start(version, "unknown-loader-network", "unobserved-loader");
    if (timing === "before declaration") {
      owner.emit(unknown); assert.throws(() => owner.arm());
    } else {
      const phase = owner.arm();
      try { owner.emit(unknown); candidate(owner); assertRejected(owner); }
      finally { phase.dispose(); }
    }
    assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0);
  });

  for (const entry of refusals) test("declared VERSION rejects " + entry.name, () => {
    const owner = fixture(entry.limit), phase = owner.arm(), events = [start(), cancel(), pause()];
    entry.mutate(events); let registered = false;
    try {
      for (const event of events) {
        if (event.method === "Fetch.requestPaused" && !registered) { owner.registerPause(event, entry.required); registered = true; }
        else owner.emit(event);
      }
      assert.ok(registered); assertRejected(owner, firstFetch, entry.response === undefined ? optional : entry.response);
    } finally { phase.dispose(); }
  });

  for (const method of ["HEAD", "POST", "PUT", "PATCH", "DELETE"]) test("declared VERSION rejects method " + method, () => {
    const owner = fixture(), phase = owner.arm(), first = start(), paused = pause();
    request(first).method = method; request(paused).method = method;
    try { owner.emit(first); owner.emit(cancel()); owner.registerPause(paused); assertRejected(owner); }
    finally { phase.dispose(); }
  });

  test("declared VERSION first successful start consumes its own lane before a second early cancellation", () => {
    const owner = fixture(), phase = owner.arm();
    try {
      owner.emit(start()); owner.emit(message("Network.responseReceived", { requestId: firstNetwork }));
      owner.emit(message("Network.loadingFinished", { requestId: firstNetwork }));
      owner.emit(start(version, secondNetwork)); owner.emit(cancel(secondNetwork)); owner.registerPause(pause(version, secondFetch, secondNetwork));
      assertRejected(owner, secondFetch);
    } finally { phase.dispose(); }
  });

  for (const source of [auth, version]) test("declared bootstrap receipt from " + source + " is refused and burned by the opposite terminal", () => {
    const owner = fixture(), phase = owner.arm(), sentinel = new Error("wrong-path receipt refused");
    const original = source === auth ? owner.lifecycle.completeDeclaredAuthRetirement.bind(owner.lifecycle) : owner.lifecycle.completeDeclaredVersionRetirement.bind(owner.lifecycle);
    const opposite = source === auth ? owner.lifecycle.completeDeclaredVersionRetirement.bind(owner.lifecycle) : owner.lifecycle.completeDeclaredAuthRetirement.bind(owner.lifecycle);
    const capture = (id: string, receipt: unknown): ReturnType<typeof original> => {
      assert.deepEqual(Object.keys(receipt as object), []); assert.equal(Object.isFrozen(receipt), true);
      const active = Reflect.get(owner.lifecycle, "activeRequests") as Map<string, { pathname: string; settlementAttemptCount: number }>;
      const entry = active.get(id); assert.ok(entry);
      const originalPath = entry.pathname;
      entry.pathname = source === auth ? version : auth;
      try { assert.throws(() => opposite(id, receipt), /declared|retirement|receipt/i); }
      finally { entry.pathname = originalPath; }
      assert.equal(entry.settlementAttemptCount, 0, "wrong-path receipt rejection must precede every settlement attempt");
      assert.equal(owner.lifecycle.activeCount, 1); assert.equal(owner.lifecycle.declaredAuthRetirementCount, 0); assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0);
      assert.throws(() => original(id, receipt), /declared|retirement|receipt/i, "wrong-path refusal must burn the genuine receipt");
      throw sentinel;
    };
    if (source === auth) owner.lifecycle.completeDeclaredAuthRetirement = capture;
    else owner.lifecycle.completeDeclaredVersionRetirement = capture;
    try {
      candidate(owner, source); assert.throws(() => owner.retire(), error => error === sentinel);
      assert.equal(owner.retire(), false); assert.equal(owner.lifecycle.activeCount, 1);
    } finally { phase.dispose(); }
  });

  for (const fault of ["owner", "id", "generation", "required", "disposed"]) test("declared VERSION opaque receipt independently refuses and burns " + fault, () => {
    const owner = fixture(), phase = owner.arm(), complete = owner.lifecycle.completeDeclaredVersionRetirement.bind(owner.lifecycle);
    owner.lifecycle.completeDeclaredVersionRetirement = (id, receipt) => {
      if (fault === "required") owner.lifecycle.setRequiredResponse(id, true);
      else if (fault === "disposed") phase.dispose();
      else {
        assert.equal(takeDeclaredVersionRetirement(receipt, fault === "owner" ? {} : owner.lifecycle,
          fault === "id" ? "foreign-fetch" : id, fault === "generation" ? owner.lifecycle.generation + 1 : owner.lifecycle.generation), false);
        assert.equal(takeDeclaredAuthRetirement(receipt, owner.lifecycle, id, owner.lifecycle.generation), false);
      }
      return complete(id, receipt);
    };
    try { candidate(owner); assert.throws(() => owner.retire(), /declared|retirement|receipt/i); assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0); assert.equal(owner.retire(), false); }
    finally { phase.dispose(); }
  });

  for (const late of ["start", "cancel"]) test("declared VERSION cannot arm retrospectively after " + late, () => {
    const owner = fixture(); owner.emit(start()); if (late === "cancel") owner.emit(cancel());
    assert.throws(() => owner.arm()); assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0);
  });

  test("declared VERSION disposal cannot rearm the same document", () => {
    const owner = fixture(), phase = owner.arm(); phase.dispose();
    assert.throws(() => owner.arm()); candidate(owner); assertRejected(owner);
  });

  test("declared VERSION cannot retire after an actual settlement attempt", () => {
    const owner = fixture(), phase = owner.arm();
    try {
      candidate(owner); const attempt = owner.lifecycle.beginSettlement(firstFetch, fulfill), original = new Error(invalidInterceptionIdMessage);
      assert.throws(() => owner.retire(), /declared|retirement|receipt/i);
      assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0); assert.equal(owner.retire(), false);
      assert.throws(() => owner.lifecycle.handleSettlementError(attempt, original), error => error === original);
    } finally { phase.dispose(); }
  });

  test("declared VERSION cannot follow a rejected original first claim", () => {
    const owner = fixture(), phase = owner.arm();
    try { candidate(owner); assert.equal(owner.proof.claimBeforeSettlement(firstFetch, fulfill, owner.input.current()), undefined); assertRejected(owner); }
    finally { phase.dispose(); }
  });

  test("the existing AUTH-only declaration grants no VERSION capability", () => {
    const owner = fixture(), phase = declareLoginReturnAuthPhase(owner.proof, owner.input, baseURL + auth);
    try { candidate(owner); assertRejected(owner); }
    finally { phase.dispose(); }
  });

  test("declared bootstrap grants no APP or unknown-route retirement", () => {
    for (const path of ["/settings/app", "/settings/app/private", "/unknown"]) {
      const owner = fixture(), phase = owner.arm();
      try { candidate(owner, path); assertRejected(owner); }
      finally { phase.dispose(); }
    }
  });

  test("declared VERSION closed and fatal owners preserve refusal and original fatal identity", () => {
    const closed = fixture(), closedPhase = closed.arm();
    try { candidate(closed); closed.state.closed = true; assertRejected(closed); }
    finally { closedPhase.dispose(); }
    const owner = fixture(), phase = owner.arm(), fatal = new Error("declared VERSION owned fatal");
    try { candidate(owner); owner.lifecycle.fail(fatal); assert.throws(() => owner.retire(), error => error === fatal); assert.equal(owner.lifecycle.declaredVersionRetirementCount, 0); }
    finally { phase.dispose(); }
  });

  test("declared bootstrap declaration requires the original proof identity and exact witnessed origin", () => {
    const owner = fixture();
    assert.throws(() => declareLoginReturnBootstrapPhase(owner.proof, { ...owner.input, lifecycle: new FetchRequestLifecycle() }, baseURL));
    assert.throws(() => declareLoginReturnBootstrapPhase(owner.proof, { ...owner.input, session: "foreign-session" }, baseURL));
    assert.throws(() => owner.arm("http://127.0.0.1:3001"));
    const initial = documentEvent(); delete (initial.params.frame as Record<string, unknown>).url;
    assert.throws(() => fixture(2048, initial).arm());
  });
}

import { existsSync } from "node:fs";

const defaultBrowserCandidates = process.platform === "win32"
  ? [
      "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
      "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe",
      "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe",
      "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe",
    ]
  : process.platform === "darwin"
    ? [
        "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
        "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge",
      ]
    : ["/usr/bin/google-chrome", "/usr/bin/google-chrome-stable", "/usr/bin/chromium", "/usr/bin/chromium-browser"];

export function resolveBrowserPath() {
  const configuredPath = process.env.AUTOSTREAM_BROWSER_PATH;
  if (configuredPath) {
    if (!existsSync(configuredPath)) throw new Error("Configured Chrome/Chromium executable was not found");
    return configuredPath;
  }
  const browserPath = defaultBrowserCandidates.find((candidate) => existsSync(candidate));
  if (!browserPath) throw new Error("Chrome/Chromium was not found; set AUTOSTREAM_BROWSER_PATH");
  return browserPath;
}

import assert from "node:assert/strict";
import test from "node:test";
import { createHarnessFixture } from "./browser-cdp-socket-fixture.mts";
import { invalidInterceptionIdMessage } from "./browser-request-lifecycle.mts";
import type { PendingCommand } from "./browser-command-deadline.mts";

const fetchID = "ordering-fetch", networkID = "ordering-network", frame = "ordering-frame";
const pathname = "/integrations/oauth-accounts", url = `http://127.0.0.1:3002${pathname}`;

function events(method = "GET") {
  return {
    document: { frame: { id: frame, loaderId: "ordering-loader", url: "http://127.0.0.1:3002/admin/" } },
    pause: { requestId: fetchID, networkId: networkID, frameId: frame, resourceType: "XHR", request: { method, url } },
    start: { requestId: networkID, frameId: frame, loaderId: "ordering-loader", type: "Fetch", request: { method, url } },
    cancel: { requestId: networkID, canceled: true, errorText: "net::ERR_ABORTED", type: "Fetch" },
  };
}

export function registerFetchOrderingCases() {
  for (const variant of [
    { name: "optional GET, Network start before pause", method: "GET", required: false, pauseFirst: false },
    { name: "optional GET, Network start after first send", method: "GET", required: false, pauseFirst: true },
    { name: "required GET", method: "GET", required: true, pauseFirst: false },
    { name: "non-GET", method: "POST", required: false, pauseFirst: false },
  ]) {
    test(`same-document in-flight cancellation preserves fatal refusal: ${variant.name}`, async () => {
      const { harness, socket } = createHarnessFixture();
      const e = events(variant.method);
      socket.hold("Fetch.fulfillRequest");
      harness.setRouteResolver(() => ({ body: [], requiredResponse: variant.required }));
      try {
        socket.emitEvent("Page.frameNavigated", e.document);
        if (!variant.pauseFirst) socket.emitEvent("Network.requestWillBeSent", e.start);
        socket.emitEvent("Fetch.requestPaused", e.pause);
        const wire = await socket.waitForCommand("Fetch.fulfillRequest");
        assert.equal(wire.params.requestId, fetchID, "settlement must use Fetch ID, never Network ID");
        if (variant.pauseFirst) socket.emitEvent("Network.requestWillBeSent", e.start);
        const idle = harness.waitForRequestHandlersIdle({ timeoutMs: 1_000 });
        const pending = (harness as unknown as { pendingCommands: Map<number, PendingCommand> }).pendingCommands.get(wire.id);
        assert.ok(pending);
        let original: Error | undefined;
        const reject = pending.reject;
        pending.reject = error => { original = error; reject(error); };
        const rejected = assert.rejects(idle, error => error === original);
        socket.emitEvent("Network.loadingFailed", e.cancel);
        socket.respond(wire, { error: { message: invalidInterceptionIdMessage } });
        await rejected;
        assert.ok(original);
        assert.throws(() => harness.assertNoFatalError(), error => error === original);
        assert.equal(socket.commandsFor("Fetch.fulfillRequest").length, 1);
        assert.equal(socket.commandsFor("Fetch.continueRequest").length, 0);
        assert.equal(harness.requests.get(pathname), 1);
        assert.equal(harness.responses.get(pathname) || 0, 0);
        const diagnostic = JSON.parse(harness.fetchFailureDiagnosticJSON!);
        assert.equal(diagnostic.request_generation, 0);
        assert.equal(diagnostic.current_generation, 0);
        assert.equal(diagnostic.cancellation_context_present, false);
        assert.equal(diagnostic.navigation_reason, "none");
        assert.equal(diagnostic.settlement_attempt, 1);
        assert.equal(diagnostic.network_cancellation_diagnostic.route, "OAUTH_ACCOUNTS");
      } finally { await harness.close(); }
    });
  }

  test("duplicate requestPaused cannot reuse an interception ID for a second send", async () => {
    const { harness, socket } = createHarnessFixture();
    const e = events();
    socket.hold("Fetch.fulfillRequest");
    harness.setRouteResolver(() => ({ body: [], requiredResponse: false }));
    try {
      socket.emitEvent("Page.frameNavigated", e.document);
      socket.emitEvent("Network.requestWillBeSent", e.start);
      socket.emitEvent("Fetch.requestPaused", e.pause);
      await socket.waitForCommand("Fetch.fulfillRequest");
      const rejected = assert.rejects(harness.waitForRequestHandlersIdle({ timeoutMs: 1_000 }), /Duplicate Fetch request ID/);
      socket.emitEvent("Fetch.requestPaused", e.pause);
      await rejected;
      assert.equal(socket.commandsFor("Fetch.fulfillRequest").length, 1);
      assert.equal(harness.responses.get(pathname) || 0, 0);
    } finally { await harness.close(); }
  });

  test("a proved cancellation before the first send never sends the expired Fetch ID", async () => {
    const { harness, socket } = createHarnessFixture();
    const e = events();
    let release!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; });
    harness.setRouteResolver(() => ({ body: [], requiredResponse: false, waitUntil: held }));
    try {
      socket.emitEvent("Page.frameNavigated", e.document);
      socket.emitEvent("Network.requestWillBeSent", e.start);
      socket.emitEvent("Fetch.requestPaused", e.pause);
      socket.emitEvent("Network.loadingFailed", e.cancel);
      const idle = harness.waitForRequestHandlersIdle({ timeoutMs: 1_000 });
      release();
      await idle;
      harness.assertNoFatalError();
      assert.equal(socket.commandsFor("Fetch.fulfillRequest").length, 0);
      assert.equal(socket.commandsFor("Fetch.continueRequest").length, 0);
      assert.equal(harness.responses.get(pathname) || 0, 0);
    } finally { release(); await harness.close(); }
  });
}

import type { FetchNavigationObservation, FetchSettlementAttempt, FetchSettlementCommand } from "./browser-request-lifecycle.mts";
import { armInFlightOAuthCancellation, disposeInFlightOAuthCancellation, prepareInFlightOAuthCancellation, prepareInFlightOptionalReadCancellation, type InFlightOAuthContext } from "./browser-inflight-oauth-cancellation.mts";

export type FetchSettlementContext = {
  observation: InFlightOAuthContext;
  closed: () => boolean; fatal: () => boolean;
  navigation: () => FetchNavigationObservation;
  send: (command: FetchSettlementCommand, params: Record<string, unknown>) => Promise<unknown>;
  reportFailure: (attempt: FetchSettlementAttempt, error: unknown) => void;
};

// Own the complete first-settlement sequence. The original claim and navigation
// error fallback are unchanged; only a separately opted-in receipt gets a branch.
export async function settleBrowserFetchRequest(context: FetchSettlementContext, requestId: string, command: FetchSettlementCommand, params: Record<string, unknown>, optedIn = false, optionalReadOptIn = false) {
  const { lifecycle, proof } = context.observation;
  const optionalRead = !optedIn && optionalReadOptIn === true;
  const observation = optionalRead ? prepareInFlightOptionalReadCancellation(context.observation, requestId, command, params, true)
    : prepareInFlightOAuthCancellation(context.observation, requestId, command, params, optedIn);
  try {
    if (!context.closed() && !context.fatal() && proof) {
      context.observation.assertHealthy();
      const current = context.observation.current();
      const ticket = proof.claimBeforeSettlement(requestId, command, { generation: lifecycle.generation, frameId: current.frameId }, optionalRead);
      if (ticket) {
        lifecycle.completePreSettlementCancellation(requestId, command, ticket);
        return false;
      }
    }
    const attempt = lifecycle.beginSettlement(requestId, command);
    armInFlightOAuthCancellation(observation, attempt);
    lifecycle.observeSettlement(requestId, context.navigation());
    try {
      await context.send(command, params);
    } catch (error) {
      if (observation && (optionalRead ? lifecycle.completeObservedInFlightOptionalReadCancellation(attempt, error)
        : lifecycle.completeObservedInFlightOAuthCancellation(attempt, error))) return false;
      try {
        lifecycle.handleSettlementError(attempt, error);
      } catch (fatalError) {
        context.reportFailure(attempt, fatalError);
        throw fatalError;
      }
      return false;
    }
    lifecycle.completeSettlement(attempt);
    return true;
  } finally { disposeInFlightOAuthCancellation(observation); }
}

