import type { BrowserNetworkCancelProof } from "./browser-network-cancel-proof.mts";
import type { FetchRequestLifecycle, FetchSettlementAttempt, FetchSettlementCommand } from "./browser-request-lifecycle.mts";

type Scope = NonNullable<ReturnType<BrowserNetworkCancelProof["ownedDocument"]>>;
type Current = { generation: number; frameId: string | undefined; closed: boolean };
export type InFlightOAuthContext = {
  owner: object; lifecycle: FetchRequestLifecycle; proof: BrowserNetworkCancelProof | undefined; session: string;
  current: () => Current; assertHealthy: () => void;
};
type Preparation = NonNullable<ReturnType<BrowserNetworkCancelProof["prepareInFlightOAuthCancellation"]>>;
type Entry = {
  family: "oauth" | "optional-read";
  context: InFlightOAuthContext; id: string; scope: Scope; origin: string; proof: Preparation;
  lifecycleLive: (attempt: FetchSettlementAttempt) => boolean; attempt?: FetchSettlementAttempt;
  command?: number; pending?: object; sent: boolean; sealed: boolean; eligible: boolean;
  invalid: boolean; disposed: boolean; wireResponses: number; error?: Error;
};
type State = { disabled: boolean; seen: Set<string>; commands: Set<number>; provisional?: Entry; pending: Map<number, Entry> };
const states = new WeakMap<object, State>();
const handles = new WeakMap<object, Entry>();
const rejected = new WeakMap<object, Entry>();
const attempts = new WeakMap<FetchSettlementAttempt, Entry>();
const origins = new WeakMap<Scope, string>();
const maxEntries = 2048;
const path = "/integrations/oauth-accounts";
const invalidID = "Invalid InterceptionId.";
const identifier = (value: unknown): value is string => typeof value === "string" && value.length > 0 && value.length <= 256;
const values = (value: unknown): Record<string, unknown> | undefined => value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : undefined;

// This records only the origin witnessed for the already-parsed owned scope.
// No opt-in, claim, clock tick or cancellation permission is created here.
export function observeInFlightOAuthDocument(proof: BrowserNetworkCancelProof, message: { sessionId?: unknown; method?: unknown; params?: unknown }, generation: number) {
  try {
    if (message.method !== "Page.frameNavigated" || !proof.ownsSession(message.sessionId)) return;
    const frame = values(values(message.params)?.frame);
    if (!frame || frame.parentId !== undefined && frame.parentId !== "" || !identifier(frame.loaderId)) return;
    const scope = identifier(frame?.id) ? proof.ownedDocument({ generation, frameId: frame.id }) : undefined;
    if (!scope || scope.loader !== frame.loaderId || scope.generation !== generation || scope.frame !== frame.id
      || typeof frame.url !== "string" || frame.url.length > 8192) return;
    const url = new URL(frame.url);
    if (["http:", "https:"].includes(url.protocol) && !url.username && !url.password) origins.set(scope, url.origin);
  } catch { /* Unknown origins cannot authorize an observation. */ }
}

function state(owner: object) {
  let value = states.get(owner);
  if (!value) { value = { disabled: false, seen: new Set(), commands: new Set(), pending: new Map() }; states.set(owner, value); }
  return value;
}

function live(entry: Entry) {
  entry.context.assertHealthy();
  const current = entry.context.current();
  return !entry.invalid && !entry.disposed && states.get(entry.context.owner)?.disabled === false && !current.closed
    && entry.context.proof?.ownedDocument(current) === entry.scope && origins.get(entry.scope) === entry.origin
    && !!entry.attempt && entry.lifecycleLive(entry.attempt);
}

function discard(entry: Entry) {
  entry.invalid = true;
  entry.disposed = true;
  entry.proof.discard();
  const value = states.get(entry.context.owner);
  if (value?.provisional === entry) value.provisional = undefined;
  if (entry.command !== undefined && value?.pending.get(entry.command) === entry) value.pending.delete(entry.command);
  if (entry.error) rejected.delete(entry.error);
  if (entry.attempt) attempts.delete(entry.attempt);
}

// This handle is a separate family from old Network tickets and declared reads.
// Even a failed opted-in preparation burns its Fetch ID; missing facts cannot be repaired later.
export function prepareInFlightOAuthCancellation(context: InFlightOAuthContext, id: string, command: FetchSettlementCommand, params: Record<string, unknown>, optedIn: boolean) {
  return prepareInFlightCancellation(context, id, command, params, optedIn, "oauth");
}

export function prepareInFlightOptionalReadCancellation(context: InFlightOAuthContext, id: string, command: FetchSettlementCommand, params: Record<string, unknown>, optedIn: boolean) {
  return prepareInFlightCancellation(context, id, command, params, optedIn, "optional-read");
}

function prepareInFlightCancellation(context: InFlightOAuthContext, id: string, command: FetchSettlementCommand, params: Record<string, unknown>, optedIn: boolean, family: Entry["family"]) {
  if (optedIn !== true) return;
  context.assertHealthy();
  const value = state(context.owner);
  if (value.disabled || !identifier(id) || value.seen.has(id)) return;
  if (value.seen.size >= maxEntries) { value.disabled = true; return; }
  value.seen.add(id);
  if (value.provisional || command !== "Fetch.fulfillRequest" || params.requestId !== id || !context.proof
    || !context.proof.ownsLifecycle(context.lifecycle, context.session)) return;
  const current = context.current(), scope = context.proof.ownedDocument(current);
  if (current.closed || !scope) return;
  const origin = origins.get(scope);
  if (!origin) return;
  const read = family === "optional-read" ? context.lifecycle.prepareInFlightOptionalReadCancellation(id) : undefined;
  const readURL = family === "optional-read" ? context.proof.optionalReadURL(id) : origin + path;
  if (!readURL || family === "optional-read" && !read) return;
  const url = new URL(readURL);
  if (!["http:", "https:"].includes(url.protocol) || !["127.0.0.1", "localhost", "[::1]"].includes(url.hostname)
    || url.origin !== origin || url.username || url.password || url.hash || family === "optional-read" && url.pathname !== read?.path) return;
  const lifecycleLive = read?.live ?? context.lifecycle.prepareInFlightOAuthCancellation(id);
  const proof = family === "optional-read" ? context.proof.prepareInFlightOptionalReadCancellation(id, current, url.href)
    : context.proof.prepareInFlightOAuthCancellation(id, current, url.href);
  if (!lifecycleLive || !proof) return;
  const entry: Entry = { family, context, id, scope, origin, proof, lifecycleLive, sent: false, sealed: false, eligible: false, invalid: false, disposed: false, wireResponses: 0 };
  const handle = Object.freeze({});
  handles.set(handle, entry);
  return handle;
}

export function armInFlightOAuthCancellation(handle: object | undefined, attempt: FetchSettlementAttempt) {
  if (!handle) return;
  const entry = handles.get(handle);
  if (!entry || entry.attempt || entry.disposed) return;
  entry.attempt = attempt;
  if (!live(entry) || !entry.proof.arm()) { discard(entry); return; }
  attempts.set(attempt, entry);
  state(entry.context.owner).provisional = entry;
}

// Called at actual command allocation, with the real pending-command object.
export function bindInFlightOAuthCommand(owner: object, id: number, pending: object | undefined, method: string, params: Record<string, unknown>, session: string | undefined) {
  const value = states.get(owner), entry = value?.provisional;
  if (!entry || !value) return;
  value.provisional = undefined;
  try {
    if (!live(entry) || !Number.isSafeInteger(id) || id < 1 || !pending || value.commands.has(id)
      || method !== "Fetch.fulfillRequest" || params.requestId !== entry.id || session !== entry.context.session
      || value.commands.size >= maxEntries) { discard(entry); if (value.commands.size >= maxEntries) value.disabled = true; return; }
    value.commands.add(id);
    entry.command = id;
    entry.pending = pending;
    value.pending.set(id, entry);
  } catch { discard(entry); }
}

// A synchronous socket throw or a synchronous response before normal return cannot qualify.
export function markInFlightOAuthSend(owner: object, id: number, pending: object | undefined) {
  const entry = states.get(owner)?.pending.get(id);
  if (!entry) return;
  try {
    if (entry.pending !== pending || entry.sent || entry.sealed || !live(entry) || !entry.proof.sent()) { discard(entry); return; }
    entry.sent = true;
  } catch { discard(entry); }
}

// Run before the Harness pending-map lookup, so a duplicate error received
// after that map's first deletion still invalidates an unconsumed receipt.
export function observeInFlightOAuthWire(owner: object, id: number) {
  const entry = states.get(owner)?.pending.get(id);
  if (!entry) return;
  entry.wireResponses += 1;
  if (entry.wireResponses !== 1) discard(entry);
}

// Must run at the actual matching CDP error response, before pending.reject.
// Returning the same Error preserves the undeclared/default error path.
export function sealInFlightOAuthRejection(owner: object, id: number, pending: object, error: Error, session: unknown) {
  const entry = states.get(owner)?.pending.get(id);
  if (!entry) return error;
  try {
    if (entry.pending !== pending || entry.sealed || !entry.sent || entry.wireResponses !== 1 || session !== entry.context.session || error.message !== invalidID || !live(entry)) { discard(entry); return error; }
    entry.sealed = true;
    entry.error = error;
    entry.eligible = entry.proof.seal();
    if (!entry.eligible) { discard(entry); return error; }
    rejected.set(error, entry);
  } catch { discard(entry); }
  return error;
}

export function discardInFlightOAuthCommand(owner: object, id: number, pending: object) {
  const entry = states.get(owner)?.pending.get(id);
  if (entry && entry.pending === pending) discard(entry);
}

// Taking burns before any owner/attempt checks. Copies and other receipt families have no entry.
export function takeInFlightOAuthCancellation(error: unknown, owner: object, attempt: FetchSettlementAttempt, validEntry: boolean, family: Entry["family"] = "oauth") {
  const byError = error !== null && typeof error === "object" ? rejected.get(error) : undefined;
  const byAttempt = attempts.get(attempt);
  if (byError && byAttempt && byError !== byAttempt) { discard(byError); discard(byAttempt); return false; }
  const entry = byError || byAttempt;
  if (!entry) return false;
  if (entry.error) rejected.delete(entry.error);
  if (entry.attempt) attempts.delete(entry.attempt);
  try {
    if (!validEntry || entry.family !== family || entry.context.lifecycle !== owner || entry.attempt !== attempt || entry.error !== error
      || !entry.sealed || !entry.eligible || !entry.sent || !live(entry)) return false;
    return entry.proof.consume();
  } finally { discard(entry); }
}

export function disposeInFlightOAuthCancellation(handle: object | undefined) {
  if (!handle) return;
  const entry = handles.get(handle);
  handles.delete(handle);
  if (entry) discard(entry);
}

import assert from "node:assert/strict";
import test from "node:test";
import { createHarnessFixture } from "./browser-cdp-socket-fixture.mts";
import { invalidInterceptionIdMessage, FetchRequestLifecycle } from "./browser-request-lifecycle.mts";
import type { BrowserNetworkCancelProof } from "./browser-network-cancel-proof.mts";
import type { PendingCommand } from "./browser-command-deadline.mts";

export function registerLateDocumentCases() {
  for (const name of ["proved old document", "commit after pause", "Network start before navigation then commit after pause", "required GET", "non-GET", "default opt-out", "foreign loader", "duplicate Network start", "new document already committed"]) {
    test(`late requestPaused during navigation: ${name}`, async () => {
      const { harness, socket } = createHarnessFixture();
      const internal = harness as unknown as { requestLifecycle: FetchRequestLifecycle; pendingCommands: Map<number, PendingCommand> };
      const path = "/settings/app", url = "http://127.0.0.1:3002" + path;
      const method = name === "non-GET" ? "POST" : "GET";
      const proved = ["proved old document", "commit after pause", "Network start before navigation then commit after pause"].includes(name);
      const frame = "late-frame", oldLoader = "late-old-loader", fetchID = "late-fetch", networkID = "late-network";
      socket.autoLoadEvent = false;
      socket.hold("Page.navigate"); socket.hold("Fetch.fulfillRequest");
      harness.setRouteResolver(() => ({ body: [], requiredResponse: name === "required GET", observeInFlightReadCancellation: name !== "default opt-out" }));
      let navigation: Promise<unknown> | undefined;
      try {
        socket.emitEvent("Page.frameNavigated", { frame: { id: frame, loaderId: oldLoader, url: "http://127.0.0.1:3002/admin/" } });
        const start = { requestId: networkID, frameId: frame, loaderId: name === "foreign loader" ? "foreign-loader" : oldLoader, type: "Fetch", request: { method, url } };
        if (name.startsWith("Network start before navigation")) socket.emitEvent("Network.requestWillBeSent", start);
        navigation = harness.navigate("http://127.0.0.1:3002/admin/streams/").catch(error => error);
        const navigate = await socket.waitForCommand("Page.navigate");
        if (name === "new document already committed") socket.emitEvent("Page.frameNavigated", { frame: { id: frame, loaderId: "new-loader", url } });
        if (!name.startsWith("Network start before navigation")) socket.emitEvent("Network.requestWillBeSent", start);
        if (name === "duplicate Network start") socket.emitEvent("Network.requestWillBeSent", start);
        socket.emitEvent("Fetch.requestPaused", { requestId: fetchID, networkId: networkID, frameId: frame, resourceType: "XHR", request: { method, url } });
        if (name.includes("commit after pause")) socket.emitEvent("Page.frameNavigated", { frame: { id: frame, loaderId: "new-loader", url } });
        const wire = await socket.waitForCommand("Fetch.fulfillRequest");
        const pending = internal.pendingCommands.get(wire.id); assert.ok(pending);
        let original: Error | undefined;
        const reject = pending.reject; pending.reject = error => { original = error; reject(error); };
        const idle = harness.waitForRequestHandlersIdle({ timeoutMs: 1_000 });
        const outcome = proved ? idle : assert.rejects(idle, error => error === original);
        socket.emitEvent("Network.loadingFailed", { requestId: networkID, canceled: true, errorText: "net::ERR_ABORTED" });
        socket.respond(wire, { error: { message: invalidInterceptionIdMessage } });
        await outcome;
        if (proved) {
          harness.assertNoFatalError();
          assert.equal(internal.requestLifecycle.safeCancellationCount, 1);
          assert.equal(internal.requestLifecycle.observedInFlightOptionalReadCancellationCount, 0, "old-document invalidation is not same-document retirement");
          socket.respond(navigate, { result: {} });
          socket.emitEvent("Page.frameNavigated", { frame: { id: frame, loaderId: "new-loader", url } });
          socket.emitEvent("Page.loadEventFired", {});
          assert.equal(await navigation, undefined);
        } else {
          assert.throws(() => harness.assertNoFatalError(), error => error === original);
          assert.equal(internal.requestLifecycle.safeCancellationCount, 0);
        }
        assert.equal(harness.responses.get(path) || 0, 0);
        assert.equal(socket.commandsFor("Fetch.fulfillRequest").length, 1);
      } finally { await harness.close(); await navigation; }
    });
  }

  for (const mode of ["single-use and unforgeable", "wrong owner burns receipt", "intervening event expires receipt"]) {
    test(`old-document registration receipt is bounded: ${mode}`, async () => {
      const { harness, socket } = createHarnessFixture();
      const { requestLifecycle: lifecycle, networkCancellation: proof } = harness as unknown as { requestLifecycle: FetchRequestLifecycle; networkCancellation: BrowserNetworkCancelProof };
      const frame = "receipt-frame", loader = "receipt-loader", fetch = "receipt-fetch", network = "receipt-network", url = "http://127.0.0.1:3002/settings/app";
      let release!: () => void;
      const held = new Promise<void>(resolve => { release = resolve; });
      harness.setRouteResolver(() => ({ body: [], requiredResponse: false, waitUntil: held }));
      socket.autoLoadEvent = false; socket.hold("Page.navigate"); socket.hold("Fetch.fulfillRequest");
      let navigation: Promise<unknown> | undefined;
      try {
        socket.emitEvent("Page.frameNavigated", { frame: { id: frame, loaderId: loader, url } });
        navigation = harness.navigate("http://127.0.0.1:3002/admin/").catch(error => error);
        const navigate = await socket.waitForCommand("Page.navigate");
        socket.emitEvent("Network.requestWillBeSent", { requestId: network, frameId: frame, loaderId: loader, type: "Fetch", request: { method: "GET", url } });
        socket.emitEvent("Fetch.requestPaused", { requestId: fetch, networkId: network, frameId: frame, resourceType: "XHR", request: { method: "GET", url } });
        const ticket = proof.claimLateDocumentRegistration(fetch, { generation: lifecycle.generation, frameId: frame });
        assert.ok(ticket);
        assert.deepEqual(Object.keys(ticket), []);
        assert.throws(() => lifecycle.bindLateDocumentRegistration(fetch, { ...ticket }), /Invalid old-document/);
        if (mode === "single-use and unforgeable") {
          lifecycle.bindLateDocumentRegistration(fetch, ticket);
          assert.throws(() => lifecycle.bindLateDocumentRegistration(fetch, ticket), /Invalid old-document/);
          assert.equal(JSON.parse(lifecycle.diagnostics()).active[0].generation, 0);
        } else {
          if (mode === "wrong owner burns receipt") {
            assert.throws(() => new FetchRequestLifecycle().bindLateDocumentRegistration(fetch, ticket), /Invalid old-document/);
          } else {
            socket.emitEvent("Network.requestWillBeSent", { requestId: "other-network", frameId: frame, loaderId: loader, type: "Fetch", request: { method: "GET", url } });
          }
          assert.throws(() => lifecycle.bindLateDocumentRegistration(fetch, ticket), /Invalid old-document/);
          assert.equal(JSON.parse(lifecycle.diagnostics()).active[0].generation, 1);
        }
        release();
        const wire = await socket.waitForCommand("Fetch.fulfillRequest");
        const idle = harness.waitForRequestHandlersIdle({ timeoutMs: 1_000 });
        socket.respond(wire, { result: {} }); await idle;
        socket.respond(navigate, { result: {} }); socket.emitEvent("Page.loadEventFired", {}); await navigation;
        harness.assertNoFatalError();
      } finally { release(); await harness.close(); await navigation; }
    });
  }
}

import assert from "node:assert/strict";
import type { UADOM } from "./browser-ua-identity.mts";

type Send = (method: string, params?: Record<string, unknown>) => Promise<Record<string, unknown>>;
type Frame = { id: string; loaderId: string };
type Part = { id: number; empty: boolean; display: string; active: number; paused: number };
type Sample = { frame: Frame; host: number; roots: number[]; error: boolean; panel?: Part; spinner?: Part };
export type NativeMediaSettlement = Readonly<{
  status: "initial-absent" | "initial-hidden" | "initial-inactive" | "observed-natural-end";
  reads: number;
}>;
const selector = "main[data-screen-family=archive-share] video[controls]";
const panelPseudo = "-internal-media-controls-loading-panel";
const spinnerPseudo = "-internal-media-controls-loading-panel-spinner-frame";

// This precedes the first AX/identity baseline. It neither creates nor resets a
// NativeFocusObserver ledger and never changes an animation or media property.
async function readSample(send: Send, source: string, read: number): Promise<Sample> {
  const group = "ui-native-media-settlement-" + read;
  let primary: unknown;
  let failed = false;
  const value = async <T,>(objectId: string, functionDeclaration: string, args: Record<string, unknown>[] = []) => {
    const response = await send("Runtime.callFunctionOn", { objectId, functionDeclaration, arguments: args, returnByValue: true });
    assert.ok(!response.exceptionDetails, "native media state read failed");
    return (response.result as { value?: T })?.value;
  };
  const frame = async () => {
    const result = await send("Page.getFrameTree");
    const current = (result.frameTree as { frame?: Frame })?.frame;
    assert.ok(current?.id && current.loaderId, "native media frame unavailable");
    return { id: current.id, loaderId: current.loaderId };
  };
  try {
    const before = await frame();
    const selected = await send("Runtime.evaluate", { expression: `(() => {const nodes=[...document.querySelectorAll(${JSON.stringify(selector)})];return nodes.length===1?nodes[0]:null;})()`, objectGroup: group, returnByValue: false });
    assert.ok(!selected.exceptionDetails, "native media host read failed");
