export const operationSelector = "#create-stream-visual [data-media-upload]";
export const submitSelector = '#create-stream form button[type="submit"]';
export type Observation = { width: number; overflow: number; candidates: number; title: string; theme: string; locale: string; cssZoom: string; operation: null | { id: string; phase: string; kind: string; text: string; progress: boolean; percent: boolean; filename: string; separate: boolean; buttonsFit: boolean }; summary: boolean; summaryVisible: boolean; uploadVisible: boolean; saveDisabled: boolean; ready: number };

export function createP3Proof(browser: BrowserHarness, directory: string | undefined, prefix: string, locale: "ja" | "en" = "ja") {
  const rows: { label: string; observation: Observation }[] = [];
  let serial = 0;
  const observe = () => browser.evaluate<Observation>(`(() => {
    const op=document.querySelector('${operationSelector}'),name=op?.querySelector('details'),actions=op?.lastElementChild;
    const rect=el=>el?.getBoundingClientRect();
    const visible=el=>{const r=rect(el);return !!r&&r.width>0&&r.height>0&&r.top>=0&&r.bottom<=innerHeight;};
    const upload=[...document.querySelectorAll('#create-stream-visual input[type=file]')].find(el=>op?.getAttribute('data-media-upload-kind')==='cover'?/蓋画像|cover image/i.test(el.closest('label')?.textContent||''):/背景画像|background image/i.test(el.closest('label')?.textContent||''));
    return {width:innerWidth,overflow:Math.max(0,document.documentElement.scrollWidth-document.documentElement.clientWidth),candidates:document.querySelectorAll('[data-cover-candidate]').length,
      title:document.querySelector('#create-stream-basic input')?.value||'',theme:document.documentElement.classList.contains('dark')?'dark':'light',locale:document.documentElement.lang,cssZoom:document.documentElement.style.zoom||'1',
      operation:op?{id:op.getAttribute('data-media-upload'),phase:op.getAttribute('data-media-upload-phase'),kind:op.getAttribute('data-media-upload-kind'),text:op.textContent||'',progress:!!op.querySelector('progress'),percent:!!op.querySelector('progress[value]'),filename:name?.querySelector('p')?.textContent||'',separate:!!name&&!!actions&&rect(actions).top>=rect(name).bottom,buttonsFit:[...op.querySelectorAll('button')].every(button=>rect(button).width>=80&&rect(button).height>=30&&rect(button).right<=rect(op).right+1)}:null,
      summary:!!document.querySelector('[data-media-upload-summary]'),summaryVisible:visible(document.querySelector('[data-media-upload-summary]')),uploadVisible:visible(upload?.closest('label')),saveDisabled:document.querySelector('${submitSelector}')?.disabled===true,ready:document.querySelectorAll('[data-media-ready-unsaved]').length};
  })()`);
  const capture = async (label: string, diagnostic = false) => {
    const anchor = await browser.evaluate<boolean>(`(() => {const el=document.querySelector('${operationSelector}')||document.querySelector('[data-cover-candidate]')||document.querySelector('#create-stream-basic')||(${diagnostic}&&document.body);if(!el)return false;el.scrollIntoView({block:'center',inline:'nearest',behavior:'instant'});return true;})()`);
    assert.equal(anchor, true); await waitForAnimationFrames(browser);
    if (!diagnostic) await browser.waitFor(`(() => {const images=[...document.querySelectorAll('#create-stream-visual [data-media-upload] img,[data-cover-candidate] img')];return images.every(image=>image.complete&&image.naturalWidth>0);})()`, Boolean, "actual pending and ready thumbnails must decode before capture");
    // Clone the DOM observation before awaiting PNG capture; later response
    // releases cannot rewrite a previous phase's evidence.
    const observation = structuredClone(await observe());
    if (!diagnostic) assert.equal(observation.overflow, 0, `${prefix}/${label} must fit the measured CSS viewport`);
    if (observation.operation && !diagnostic) { assert.equal(observation.summaryVisible, true, "the count summary stays readable after scrolling to the active card"); assert.equal(observation.operation.separate, true); assert.equal(observation.operation.buttonsFit, true); assert.equal(observation.operation.text.includes(unsafeErrorProbe), false); }
    rows.push({ label, observation });
    if (directory) {
      mkdirSync(directory, { recursive: true }); const filename = `${prefix}-${String(++serial).padStart(3, "0")}-${label}`;
      const image = await browser.captureViewportEvidence();
      writeFileSync(resolve(directory, `${filename}.png`), image.png, { flag: "wx" });
      writeFileSync(resolve(directory, `${filename}.json`), JSON.stringify({ observation, viewport: image.viewport, evidence_kind: "real_browser_CSS_viewport", css_200_is_native_zoom: false }, null, 2), { flag: "wx" });
    }
    return observation;
  };
  const phase = async (kind: ImageKind, value: string, candidates: number, filename?: string) => {
    await browser.waitFor(`document.querySelector('${operationSelector}')?.getAttribute('data-media-upload-kind')===${JSON.stringify(kind)}&&document.querySelector('${operationSelector}')?.getAttribute('data-media-upload-phase')===${JSON.stringify(value)}`, Boolean, `${kind} actual ${value} phase missing`);
    const current = await observe();
    const phaseText: Record<string, string> = locale === "ja"
      ? { preparing: "準備中", uploading: "アップロード中", converting: "画像を変換中", checking: "画像の状態を確認中", cleaning: "一時画像を取り消し中", failed: "画像の処理に失敗しました。", outcome_unknown: "画像の処理結果が不明です。" }
      : { preparing: "Preparing", uploading: "Uploading", converting: "Converting image", checking: "Checking image status", cleaning: "Discarding temporary image", failed: "The image could not be processed.", outcome_unknown: "The image result is unknown." };
    assert.ok(phaseText[value]); assert.equal(current.operation?.text.includes(phaseText[value]), true, "the visible phase must use the selected locale");
    assert.equal(current.candidates, candidates, "pending, failed and unknown images must never enter ready candidates");
    assert.equal(current.saveDisabled, true); assert.equal(current.summary, true);
    assert.equal(current.operation?.percent, false, "actual work must use indeterminate progress, never an invented percentage");
    assert.equal(current.operation?.progress, ["preparing", "uploading", "converting", "checking", "cleaning"].includes(value));
    if (filename) assert.equal(current.operation?.filename, filename);
    await clickDisabledVisible(browser, submitSelector);
  };
  const action = async (locale: "ja" | "en", name: "check" | "resume" | "retry" | "discard") => clickVisible(browser, `${operationSelector} button`, new RegExp(`^${labels[locale][name]}$`));
  const ready = async (count: number, locale: "ja" | "en", minimumBadges: number) => {
    await browser.waitFor(`!document.querySelector('${operationSelector}')&&document.querySelectorAll('[data-cover-candidate]').length===${count}&&document.querySelectorAll('[data-media-ready-unsaved]').length>=${minimumBadges}`, Boolean, "only a finished response may become ready-unsaved");
    assert.equal(await browser.evaluate(`document.querySelector('#create-stream-visual')?.textContent?.includes(${JSON.stringify(labels[locale].ready)})`), true);
  };
  const layouts = async (label: string, originalWidth: number) => {
    for (const width of [320, 390, 1440]) {
      await browser.setViewport(width, 1000); const row = await capture(`${label}-css-${width}`); assert.equal(row.width, width);
    }
    for (const width of [390, 1440]) {
      await browser.setViewport(width, 1000);
      try { await browser.evaluate("document.documentElement.style.zoom='2';true"); const row = await capture(`${label}-css-${width}-magnification-200`); assert.equal(row.cssZoom, "2"); }
      finally { await browser.evaluate("document.documentElement.style.zoom='';true"); }
    }
    await browser.setViewport(originalWidth, 1000);
  };
  return { rows, observe, phase, capture, action, ready, layouts,
    revealFilename: async () => {
      // A retry can retain the same native details element in its open state.
      // Establish the closed starting state with real input before testing reveal.
      if (await browser.evaluate(`document.querySelector('${operationSelector} details')?.hasAttribute('open')`)) {
        await clickVisible(browser, `${operationSelector} details summary`);
        await browser.waitFor(`!document.querySelector('${operationSelector} details')?.hasAttribute('open')`, Boolean, "native click must close an already expanded filename");
      }
      await clickVisible(browser, `${operationSelector} details summary`);
      await browser.waitFor(`document.querySelector('${operationSelector} details')?.hasAttribute('open')`, Boolean, "native click must reveal the full filename");
      await scrollSelectorIntoView(browser, `${operationSelector} details p`);
      assert.equal(await browser.evaluate(`document.querySelector('${operationSelector} details')?.hasAttribute('open')`), true);
    },
  };
}

import assert from "node:assert/strict";
import { mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { BrowserHarness, type StubRequest, type StubResponse } from "./browser-harness.mts";
import { createBrowserRouteFixture, currentUser, healthyRows } from "../ui-browser-fixture.mts";
import { clickVisible } from "../ui-regression/visible-trigger.mts";
import { waitForAnimationFrames } from "../ui-browser-navigation-helpers.mts";

export type RelatedRequest = Readonly<{ method: string; path: string; body?: Record<string, unknown> }>;
export type RelatedCaseResult = { name: string; status: "PASS" | "FAIL" | "NOT_RUN"; error_class?: string;
  request_counts?: Record<string, number>; response_counts?: Record<string, number>; captures?: string[];
  body_started?: boolean; diagnostic_errors?: { phase: string; error_class: string }[] };
type Handler = (request: StubRequest) => StubResponse;
type Gate = { entered: Promise<void>; release: () => void };

export type RelatedBrowserContext = ReturnType<typeof createRelatedBrowserContext>;

export function createRelatedBrowserContext(browser: BrowserHarness, baseURL: string, evidenceDirectory: string) {
  const routes = new Map<string, Handler>();
  const requests: RelatedRequest[] = [];
  const gates = new Map<string, { enter: () => void; wait: Promise<void>; release: () => void }>();
  const gateReleases = new Set<() => void>();
  const cases: RelatedCaseResult[] = [];
  const captures: string[] = [];
  const completedCycles: { name: string; paths: readonly string[]; cycles: number; trigger: string }[] = [];
  const mobileOperations: { name: string; width: number }[] = [];
  const failures: Error[] = [];
  const attemptedNames = new Set<string>();
  let browserReady = true;
  let isolationFailure: Error | undefined;
  let currentCase = "not-started";
  const installRoutes = (): ReturnType<typeof createBrowserRouteFixture> => createBrowserRouteFixture(browser, (request): StubResponse | null => {
    const path = new URL(request.url).pathname.replace(/\/$/, "") || "/";
    if (!/^\/(auth|setup|settings|account|workers|nodes|service-health|system-updates|version|profiles|discord|security|secrets|roles|streams)/.test(path)) return null;
    const key = `${request.method} ${path}`;
    let body: Record<string, unknown> | undefined;
    if (request.postData) { try { body = JSON.parse(request.postData); } catch { /* Non-JSON requests are never copied into evidence. */ } }
    requests.push({ method: request.method, path, ...(body ? { body } : {}) });
    const handler = routes.get(key);
    const gate = gates.get(key);
    if (!handler && !gate) return null;
    const response: StubResponse = handler ? handler(request) : path === "/auth/me" ? fixture.authResponse : { body: [] };
    if (!gate) return response;
    gates.delete(key);
    gate.enter();
    return { ...response, waitUntil: response.waitUntil ? Promise.all([response.waitUntil, gate.wait]).then(() => undefined) : gate.wait };
  });
  let fixture: ReturnType<typeof createBrowserRouteFixture> = installRoutes();
  const control = {
    requests,
    set(method: string, path: string, response: StubResponse) { routes.set(`${method} ${path}`, () => response); },
    handle(method: string, path: string, handler: Handler) { routes.set(`${method} ${path}`, handler); },
    count(method: string, path: string) { return requests.filter((request) => request.method === method && request.path === path).length; },
    gateNext(method: string, path: string): Gate {
      const key = `${method} ${path}`;
      assert.equal(gates.has(key), false, `one owned gate per ${key}`);
      let enter!: () => void, release!: () => void;
      const entered = new Promise<void>((done) => { enter = done; });
      const wait = new Promise<void>((done) => { release = done; });
      gateReleases.add(release);
      gates.set(key, { enter, wait, release });
      return { entered, release };
    },
    reset() {
      for (const release of gateReleases) release();
      gateReleases.clear();
      gates.clear(); routes.clear(); requests.length = 0;
      routes.set("GET /roles", () => ({ body: [] }));
      routes.set("GET /secrets/status", () => ({ body: [] }));
      fixture.authResponse = { body: currentUser };
      fixture.workersResponse = { body: healthyRows };
      fixture.nodesResponse = { body: healthyRows };
      fixture.healthResponse = { body: healthyRows };
      browser.clearRequestCounts();
    },
    releaseAll() { for (const release of gateReleases) release(); gateReleases.clear(); gates.clear(); },
  };
  async function navigate(path: string, readySelector = "main") {
    await browser.navigate(new URL(path, baseURL).href);
    await browser.waitFor(`!!document.querySelector(${JSON.stringify(readySelector)})`, Boolean, `actual ${path} UI did not mount`, 30_000);
    await browser.waitForRequestHandlersIdle({ pathname: "/auth/me", method: "GET" });
  }
  async function click(text: string, scope = "main") {
    const escaped = text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    await clickVisible(browser, `${scope} button`, new RegExp(`^${escaped}$`));
  }
  async function fill(selector: string, value: string) {
    await browser.evaluate(`document.querySelector(${JSON.stringify(selector)})?.scrollIntoView({block:'center',inline:'nearest'});true`);
    await browser.fillSelector(selector, value);
    await browser.waitFor(`document.querySelector(${JSON.stringify(selector)})?.value`, (actual) => actual === value, "controlled input did not retain the explicit draft");
  }
  async function readValue(selector: string) {
    return browser.evaluate<string | null>(`document.querySelector(${JSON.stringify(selector)})?.value ?? null`);
  }
  async function settleQueryConsumers() {
    // Fetch.fulfillRequest acknowledgement precedes the page's response.json(),
    // query success notification and React commit. A subsequent focus event can
    // otherwise reuse that query's still-active promise (cancelRefetch:false).
    await waitForAnimationFrames(browser);
    await browser.waitFor(`(() => {
      const workers=document.querySelector('[data-screen-family="workers"]');
      if(!workers)return true;
      const refresh=[...workers.querySelectorAll('button[aria-busy]')].filter(button=>button.textContent.trim().startsWith('Refresh'));
      return refresh.length===1 && refresh[0].getAttribute('aria-busy')==='false';
    })()`, Boolean, "the real Worker query consumer must commit its completed refresh before the next focus event");
    await waitForAnimationFrames(browser);
  }
  async function focusCycle(paths: readonly string[]) {
    assert.ok(paths.length > 0);
    await Promise.all(paths.map((path) => browser.waitForRequestHandlersIdle({ pathname: path, method: "GET" })));
    await settleQueryConsumers();
    const before = paths.map((path) => browser.responses.get(path) || 0);
    // This delivers the browser focus-manager event to the real mounted query
    // owners. It does not call fetch, a queryClient, or a controller in the page.
    await browser.evaluate("document.dispatchEvent(new Event('visibilitychange',{bubbles:true}));true");
    await Promise.all(paths.map((path, index) => browser.waitForResponseCount(path, before[index] + 1, 20_000)));
    await Promise.all(paths.map((path) => browser.waitForRequestHandlersIdle({ pathname: path, method: "GET" })));
    await settleQueryConsumers();
  }
  async function completeCycles(paths: readonly string[], cycles: number) {
    assert.equal(cycles, 3, "targeted polling acceptance requires three completed cycles");
    for (let cycle = 0; cycle < cycles; cycle++) await focusCycle(paths);
    completedCycles.push({ name: currentCase, paths: [...paths], cycles, trigger: "visibilitychange focus-manager; actual query GET response, handler-idle, animation-frame and rendered refresh-completion barriers" });
  }
  async function capture(label: string, focusSelector?: string) {
    assert.match(label, /^[a-z0-9-]+$/);
    mkdirSync(evidenceDirectory, { recursive: true });
    for (const width of [1440, 390, 320]) {
      await browser.setViewport(width, 1000);
      if (focusSelector) await browser.evaluate(`document.querySelector(${JSON.stringify(focusSelector)})?.scrollIntoView({block:'center',inline:'nearest'});true`);
      const snapshot = structuredClone(await browser.evaluate(`({width:innerWidth,viewport:document.documentElement.clientWidth,overflow:Math.max(0,document.documentElement.scrollWidth-document.documentElement.clientWidth),dialogs:document.querySelectorAll('[role=dialog],[role=alertdialog]').length,fields:[...document.querySelectorAll('main input,[role=dialog] input,[role=alertdialog] input')].filter(e=>e.getClientRects().length).map(e=>({type:e.type,id:e.id,disabled:e.disabled,length:e.value.length})),active:{tag:document.activeElement?.tagName||'',id:document.activeElement?.id||''}})`));
      const image = await browser.captureViewportEvidence();
      const stem = `${label}-${width}`;
      writeFileSync(resolve(evidenceDirectory, `${stem}.png`), image.png, { flag: "wx" });
      writeFileSync(resolve(evidenceDirectory, `${stem}.json`), JSON.stringify(snapshot, null, 2), { flag: "wx" });
      captures.push(stem);
    }
    await browser.setViewport(1440, 1000);
  }
  async function operateAt(width: 1440 | 390 | 320, body: () => Promise<void>) {
    await browser.setViewport(width, 1000);
    mobileOperations.push({ name: currentCase, width });
    try { await body(); } finally { await browser.setViewport(1440, 1000); }
  }
  const asError = (error: unknown) => error instanceof Error ? error : new Error("Related browser fixture threw a non-Error value", { cause: error });
  function retainCaseFailure(result: RelatedCaseResult, phase: string, error: unknown) {
    const retained = asError(error);
    failures.push(retained);
    result.status = "FAIL";
    result.error_class ||= retained.name;
    (result.diagnostic_errors ??= []).push({ phase, error_class: retained.name });
    return retained;
  }
  async function closeBrowser() {
    browserReady = false;
    try { await browser.close(); }
    catch (error) { isolationFailure ||= asError(error); throw error; }
  }
  async function captureCaseFailure(result: RelatedCaseResult, label: string) {
    if (!browserReady) return;
    try { await capture(label); }
    catch (error) { retainCaseFailure(result, "failure-capture", error); }
  }
  async function check(name: string, body: () => Promise<void>) {
    const result: RelatedCaseResult = cases.find((item) => item.name === name) ?? { name, status: "NOT_RUN" };
    if (!cases.includes(result)) cases.push(result);
    assert.equal(result.status, "NOT_RUN", "named acceptance case executes once");
    assert.equal(attemptedNames.has(name), false, "each named case receives one isolated execution attempt");
    attemptedNames.add(name);
    result.body_started = false;
    if (isolationFailure) {
      result.error_class = isolationFailure.name;
      result.diagnostic_errors = [{ phase: "not-run-isolation-unavailable", error_class: isolationFailure.name }];
      return; // Keep NOT_RUN; an unverified old process forbids another launch.
    }
    const captureStart = captures.length;
    const failureLabel = `case-${String(cases.indexOf(result) + 1).padStart(2, "0")}-failure`;
    let caseRoutesReady = false;
    currentCase = name;
    try {
      // A previous failed/conflicted draft can own a beforeunload guard. Close
      // its owned process instead of weakening that guard or accepting dialogs.
      if (attemptedNames.size > 1) {
        control.releaseAll();
        await closeBrowser();
        try { browser = await BrowserHarness.launch(); }
        catch (error) { isolationFailure = asError(error); throw error; }
        browserReady = true;
        fixture = installRoutes();
      }
      control.reset();
      caseRoutesReady = true;
      await browser.configureDeterministicDocument({
        source: "localStorage.setItem('autostream.controlPanel.locale','en');localStorage.setItem('autostream.ui_preference',JSON.stringify({theme_id:'autostream',color_mode:'light'}));sessionStorage.setItem('autostream.csrf_token','related-fixture-csrf');",
        timezone: "Asia/Tokyo", locale: "en-US",
      });
      await browser.setViewport(1440, 1000);
      result.body_started = true;
      await body();
      result.status = "PASS";
    }
    catch (error) {
      retainCaseFailure(result, result.body_started ? "case-body" : "case-setup-or-close", error);
      await captureCaseFailure(result, failureLabel);
    }
    finally {
      try { control.releaseAll(); }
      catch (error) {
        retainCaseFailure(result, "case-gate-cleanup", error);
        await captureCaseFailure(result, `${failureLabel}-cleanup`);
      }
      result.request_counts = {};
      for (const request of caseRoutesReady ? requests : []) {
        const key = `${request.method} ${request.path}`;
        result.request_counts[key] = (result.request_counts[key] || 0) + 1;
      }
      result.response_counts = caseRoutesReady ? Object.fromEntries(browser.responses) : {};
      result.captures = captures.slice(captureStart);
    }
  }
  return { get browser() { return browser; }, get failures() { return [...failures]; }, baseURL, evidenceDirectory, width: 1440, fixture: control, cases, captures, completedCycles, mobileOperations,
    navigate, click, fill, readValue, focusCycle, completeCycles, capture, operateAt, check,
    closeBrowser,
    plan(names: readonly string[]) { for (const name of names) { assert.equal(cases.some((item) => item.name === name), false); cases.push({ name, status: "NOT_RUN" }); } },
  };
}

import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { clickVisible } from "../ui-regression/visible-trigger.mts";
import { withTimeout } from "./browser-process-timing.mts";
import type { RelatedBrowserContext } from "./polling-related-browser-context.mts";

export const discordPath = "/discord/configs";
export const securityPath = "/security/settings";
export const originalStamp = "2026-10-28T00:00:00.123457Z";
export const secondStamp = "2026-10-28T00:00:00.123458Z";
export const thirdStamp = "2026-10-28T00:00:00.123459Z";
export const resourceName = '[role="dialog"] form input[type="text"]';
export const resourceSubmit = '[role="dialog"] form button[type="submit"]';
export const securityInput = '[data-related-security-min]';
export const securitySubmit = 'main form button[type="submit"]';
const confirmation = '[role="alertdialog"] [data-confirm-action]';

export async function click(ctx: RelatedBrowserContext, selector: string) {
  await clickVisible(ctx.browser, selector);
}

export async function waitText(ctx: RelatedBrowserContext, scope: string, text: string) {
  await ctx.browser.waitFor(`document.querySelector(${JSON.stringify(scope)})?.textContent.includes(${JSON.stringify(text)})`, Boolean, "the real UI must display its terminal action outcome");
}

export async function openConfirmation(ctx: RelatedBrowserContext, submitSelector: string) {
  await click(ctx, submitSelector);
  await waitConfirmation(ctx);
}

export async function waitConfirmation(ctx: RelatedBrowserContext) {
  await ctx.browser.waitFor(`(() => {const e=document.querySelector(${JSON.stringify(confirmation)});return e instanceof HTMLButtonElement && !e.disabled && e.getClientRects().length>0;})()`, Boolean, "the actual confirmation must become enabled after fresh reads");
}

export async function confirmWrite(ctx: RelatedBrowserContext, method: string, path: string) {
  const gate = ctx.fixture.gateNext(method, path);
  try {
    await click(ctx, confirmation);
    await withTimeout(gate.entered, 8_000, "the one confirmed mutation must reach its actual HTTP boundary");
  } finally { gate.release(); }
  await ctx.browser.waitForRequestHandlersIdle({ pathname: path, method });
}

export async function confirmReadOnlyRejection(ctx: RelatedBrowserContext, outcome: string) {
  const gate = ctx.fixture.gateNext("GET", "/auth/me");
  try {
    await click(ctx, confirmation);
    await withTimeout(gate.entered, 8_000, "confirmation must perform its fresh permission read");
  } finally { gate.release(); }
  await ctx.browser.waitForRequestHandlersIdle({ pathname: "/auth/me", method: "GET" });
  await waitText(ctx, "main", outcome);
}

export async function noConfirmation(ctx: RelatedBrowserContext) {
  await ctx.browser.waitFor("document.querySelector('[role=alertdialog]') === null", Boolean, "the completed action must settle its confirmation");
}

export async function markSecurityInput(ctx: RelatedBrowserContext) {
  await ctx.browser.waitFor(`(() => {const e=document.querySelector('main form input[type=number]');if(!(e instanceof HTMLInputElement)||e.disabled)return false;e.setAttribute('data-related-security-min','');return e.value==='12';})()`, Boolean, "the real security editor must hydrate its original policy");
}

export async function watchInput(ctx: RelatedBrowserContext, selector: string, expected: string) {
  await click(ctx, selector);
  assert.equal(await ctx.readValue(selector), expected);
  await ctx.browser.evaluate(`globalThis.__relatedPollingInput=document.querySelector(${JSON.stringify(selector)});true`);
}

export async function assertRetainedFocus(ctx: RelatedBrowserContext, selector: string, expected: string) {
  assert.equal(await ctx.browser.evaluate(`(() => {const e=globalThis.__relatedPollingInput;return e instanceof HTMLInputElement&&e.isConnected&&e===document.querySelector(${JSON.stringify(selector)})&&document.activeElement===e&&e.value===${JSON.stringify(expected)};})()`), true, "the same real draft input, value and focus must survive query completion");
}

export async function threeSlowFocusCycles(ctx: RelatedBrowserContext, paths: readonly string[], selector: string, expected: string) {
  const gate = ctx.fixture.gateNext("GET", "/auth/me");
  const cycles = ctx.completeCycles(paths, 3);
  void cycles.catch(() => {});
  try {
    await withTimeout(gate.entered, 8_000, "the first controlled focus cycle must start its slow actual GET");
    await assertRetainedFocus(ctx, selector, expected);
  } finally { gate.release(); }
  await cycles;
  await assertRetainedFocus(ctx, selector, expected);
}

export async function captureProof(ctx: RelatedBrowserContext, label: string, selector?: string) {
  const operationWidth = await ctx.browser.evaluate<number>("innerWidth");
  await ctx.capture(label, selector);
  for (const width of [1440, 390, 320]) {
    const snapshot = JSON.parse(readFileSync(resolve(ctx.evidenceDirectory, `${label}-${width}.json`), "utf8")) as { width: number; overflow: number };
